const state={catalog:null,cart:[],detail:null,detailQty:1,detailNote:"",drawer:null,checkoutType:"delivery",checkoutFeeCents:0,lastOrder:null,tracking:{code:null,status:null,timer:null},tables:{data:null,timer:null},admin:{logged:false,view:"orders",orders:[],tables:null,posCart:[],posWaiterFee:false,orderFilter:"all",revenue:null,printStatus:null,refresh:null,editOrderId:null,editOrderCart:[]},cashier:{branch:"",name:"",view:"orders",orders:[],catalog:null,posCart:[],orderFilter:"all",revenue:null,scale:null,selfService:null,refresh:null}};
const $=s=>document.querySelector(s); const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[c]));
const money=c=>new Intl.NumberFormat("pt-BR",{style:"currency",currency:"BRL"}).format((Number(c)||0)/100);const eta=v=>/^\d+$/.test(String(v||""))?`${v} min`:String(v||"");
const slug=s=>String(s).normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"");
// Taxas e bairros ficam vazios até o proprietário cadastrar os dados reais da Açaí Prime.
const DELIVERY_NEIGHBORHOODS={Petrolina:[],Juazeiro:[]};
// Identidade visual pública cadastrada pela própria Açailandia no RV Pedidos.
const JW_LOGO="https://storage.googleapis.com/prod-cardapio-web/uploads/company/logo/14701/9f065ffdREQUISITOS_RV__4_.png";
const PIX_KEY="",PIX_KEY_DISPLAY="Configure no painel",PIX_MERCHANT="ACAILANDIA PE",PIX_CITY="PETROLINA";
const api=async(path,options={})=>{const isForm=options.body instanceof FormData,controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),20000),headers={...(isForm?{}:{"content-type":"application/json"}),...(options.headers||{})};try{const res=await fetch(path,{...options,headers,signal:controller.signal});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.error||"Não foi possível concluir.");return data}catch(error){if(error?.name==="AbortError")throw new Error("A conexão demorou mais que o esperado. Tente novamente.");throw error}finally{clearTimeout(timeout)}};
function toast(message){const el=$("#toast");el.textContent=message;el.classList.add("show");clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove("show"),2600)}
function cartCount(cart=state.cart){return cart.reduce((s,i)=>s+i.quantity,0)}function itemUnitPrice(i){return Number(i.unit_price_cents??i.product.price_cents)||0}function cartTotal(cart=state.cart){return cart.reduce((s,i)=>s+i.quantity*itemUnitPrice(i),0)}function checkoutTotal(){return cartTotal()+(state.checkoutType==="delivery"?Number(state.checkoutFeeCents||0):0)}
function normalizedNeighborhood(value){return String(value||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().trim().replace(/\s+/g," ")}
function deliveryFeeForNeighborhood(value){const s=state.catalog?.settings||{},rule=(s.delivery_neighborhood_fees||[]).find(item=>normalizedNeighborhood(item.neighborhood)===normalizedNeighborhood(value));const base=Number(rule?.fee_cents||0);return base&&s.delivery_surcharge_enabled?Math.round(base*(1+Math.max(0,Number(s.delivery_surcharge_percent||0))/100)):base}
function updateCheckoutFee(){const input=$("[name=neighborhood]");state.checkoutFeeCents=state.checkoutType==="delivery"?deliveryFeeForNeighborhood(input?.value):0;const fee=$("#checkout-fee"),total=$("#checkout-total");if(fee)fee.textContent=money(state.checkoutFeeCents);if(total)total.textContent=money(checkoutTotal())}
function cartItemKey(product,complements=[],notes=""){return `${product.id}:${JSON.stringify(complements)}:${notes}`}
function getCartItem(key,cart=state.cart){return cart.find(i=>i.key===String(key)||String(i.product.id)===String(key))}
function addItem(product,quantity=1,cart=state.cart,complements=[],notes=""){const selected=complements.filter(item=>item.quantity>0),key=cartItemKey(product,selected,notes),isFlavorPricedBottle=Number(product.id)===1,unit=isFlavorPricedBottle&&selected.length===1?Number(selected[0].price_cents):product.price_cents+selected.reduce((sum,item)=>sum+item.price_cents*item.quantity,0),item=getCartItem(key,cart);if(item)item.quantity=Math.min(20,item.quantity+quantity);else cart.push({product,quantity,key,complements:selected,notes,unit_price_cents:unit});}
function updateQty(key,delta,cart=state.cart){const item=getCartItem(key,cart);if(!item)return;item.quantity+=delta;if(item.quantity<=0)cart.splice(cart.indexOf(item),1)}
function statusLabel(s){return({novo:"Novo",confirmado:"Confirmado",preparando:"Preparando",pronto:"Pronto",saiu_entrega:"Saiu para entrega",concluido:"Concluído",cancelado:"Cancelado"})[s]||s}
function paymentLabel(s){return({dinheiro:"Dinheiro",pix:"Pix",credito:"Cartão de crédito",debito:"Cartão de débito",misto:"Pagamento dividido"})[s]||s||"Não informado"}
function orderTypeLabel(s){return({pickup:"Retirada",dine_in:"Consumir no local",delivery:"Entrega/Delivery"})[s]||"Retirada"}
function safeMapsUrl(value){const url=String(value||"").trim();return /^https:\/\/(maps\.app\.goo\.gl|goo\.gl\/maps|maps\.google\.[a-z.]+|www\.google\.[a-z.]+\/maps)(\/|\?|$)/i.test(url)?url:""}
function orderAddressMarkup(o){if(!o.address&&!o.city)return"";if(!o.city)return `<div class="order-meta address-summary">${esc(o.address)}</div>`;const parts=[`${o.street||""}, ${o.house_number||""}`,o.block?`Bloco: ${o.block}`:"",`${o.neighborhood||""} • ${o.city||""}`,`Referência: ${o.reference_point||""}`,o.complement?`Complemento: ${o.complement}`:""];const map=safeMapsUrl(o.maps_url);return `<div class="order-address">${parts.filter(Boolean).map(p=>`<span>${esc(p)}</span>`).join("")}${map?`<a href="${esc(map)}" target="_blank" rel="noopener noreferrer">Abrir no Google Maps</a>`:""}</div>`}
function rememberOrder(id){try{localStorage.setItem("loja_last_order",id)}catch{}state.lastOrder={...(state.lastOrder||{}),id}}
function phoneForWhatsApp(value){const digits=String(value||"").replace(/\D/g,"");return digits.startsWith("55")?digits:`55${digits}`}
function whatsappUrl(phone,message){return `https://wa.me/${phoneForWhatsApp(phone)}?text=${encodeURIComponent(message)}`}
function pixTlv(id,value){const text=String(value);return `${id}${String(text.length).padStart(2,"0")}${text}`}
function pixCrc(value){let crc=0xffff;for(let i=0;i<value.length;i++){crc^=value.charCodeAt(i)<<8;for(let bit=0;bit<8;bit++)crc=(crc&0x8000)?((crc<<1)^0x1021)&0xffff:(crc<<1)&0xffff}return crc.toString(16).toUpperCase().padStart(4,"0")}
function pixPayload(totalCents,orderId){const merchant=pixTlv("00","br.gov.bcb.pix")+pixTlv("01",PIX_KEY),amount=(Math.max(0,Number(totalCents)||0)/100).toFixed(2),txid=String(orderId||"***").replace(/[^A-Za-z0-9]/g,"").slice(0,25)||"***",base=pixTlv("00","01")+pixTlv("26",merchant)+pixTlv("52","0000")+pixTlv("53","986")+pixTlv("54",amount)+pixTlv("58","BR")+pixTlv("59",PIX_MERCHANT)+pixTlv("60",PIX_CITY)+pixTlv("62",pixTlv("05",txid))+"6304";return base+pixCrc(base)}
function pixQrUrl(payload){return `https://quickchart.io/qr?text=${encodeURIComponent(payload)}&size=320&margin=2&ecLevel=M&format=svg`}
function pixPaymentMarkup(order){if(order.payment_method!=="pix")return"";const payload=pixPayload(order.total_cents,order.id);return `<section class="pix-payment"><div class="pix-heading"><span class="pix-symbol">PIX</span><div><strong>Pague ${money(order.total_cents)} pelo Pix</strong><small>O QR Code já contém o valor total deste pedido.</small></div></div><img class="pix-qr" src="${esc(pixQrUrl(payload))}" alt="QR Code Pix do pedido ${esc(order.id)}" referrerpolicy="no-referrer"><div class="pix-key">Chave Pix: <strong>${PIX_KEY_DISPLAY}</strong></div><textarea class="pix-copy-value" readonly>${esc(payload)}</textarea><button type="button" class="secondary-btn full whatsapp-copy" data-copy-pix="${esc(payload)}">Copiar código Pix</button><small class="pix-help">Abra o aplicativo do seu banco e escolha Pix Copia e Cola. Confirme o nome do recebedor antes de pagar.</small></section>`}
function orderItemsForMessage(order){return (order.items||[]).map(item=>{let line=`${item.quantity}x ${String(item.product_name||item.product?.name||"").toUpperCase()} - ${money(item.quantity*Number(item.unit_price_cents||item.product?.price_cents||0))}`;let complements=item.complements;try{if(!complements&&item.complements_json)complements=JSON.parse(item.complements_json)}catch{}if(complements?.length)line+=`\n   + ${complements.map(option=>`${option.quantity||1}x ${option.name}`).join(", ")}`;if(item.notes)line+=`\n   OBS: ${item.notes}`;return line}).join("\n\n")}
function customerOrderMessage(order){const s=state.catalog?.settings||{},date=new Date(order.created_at?`${order.created_at}Z`:Date.now()).toLocaleString("pt-BR"),delivery=order.order_type==="delivery",address=delivery?`\n---\n\nENDEREÇO DE ENTREGA 🛵💨\nRUA: ${order.street||"Não informada"}\nNÚMERO: ${order.house_number||"Não informado"}\nBAIRRO: ${order.neighborhood||"Não informado"}${order.city?` - ${order.city}`:""}${order.reference_point?`\nREFERÊNCIA: ${order.reference_point}`:""}${order.complement?`\nCOMPLEMENTO: ${order.complement}`:""}\n`:"";return `🍽️ AÇAILANDIA PE 🍽️\n🗓️ REALIZADO EM: ${date}\nPEDIDO: ${order.id}\n\nCLIENTE: ${String(order.customer_name||"Cliente").toUpperCase()}\nTEL: ${String(order.phone||"").replace(/\D/g,"")}\n----------------\n\n${orderItemsForMessage(order)}\n\n---\n\nSUBTOTAL: ${money(order.subtotal_cents)}\nVALOR DA ENTREGA: ${money(order.delivery_fee_cents||0)}\nTOTAL: ${money(order.total_cents)}\n${address}\n---\n\nFORMA DE PAGAMENTO: ${paymentLabel(order.payment_method)}${order.payment_method==="pix"?" 📱":""}\n\n✅ PEDIDO ENVIADO ✅\nPREVISÃO DE ${delivery?"ENTREGA":"RETIRADA"}: ${delivery?eta(s.delivery_eta):eta(s.pickup_eta)}\nPRAZO P/ CANCELAR: 3 MIN`}
function ownerStatusMessage(order){const messages={novo:"Recebemos seu pedido e ele aguarda confirmação.",confirmado:"Seu pedido foi confirmado!",preparando:"Seu pedido está sendo preparado com carinho.",pronto:order.order_type==="delivery"?"Seu pedido está pronto e logo sairá para entrega.":"Seu pedido está pronto para retirada!",saiu_entrega:"Seu pedido saiu para entrega 🛵💨",concluido:"Seu pedido foi concluído. Obrigado pela preferência!",cancelado:`Seu pedido foi cancelado.${order.cancel_reason?` Motivo: ${order.cancel_reason}`:""}`};return `🍽️ *AÇAILANDIA PE* 🍽️\n\nOlá, ${order.customer_name||"cliente"}!\nPedido: *${order.id}*\n\n${messages[order.status]||`Situação do pedido: ${statusLabel(order.status)}.`}\n\nTotal: *${money(order.total_cents)}*\n\nAcompanhe em:\nhttps://açailandia.wpnz.com.br/`}
async function copyPix(value){try{await navigator.clipboard.writeText(value);toast("Código Pix copiado")}catch{const area=document.createElement("textarea");area.value=value;document.body.appendChild(area);area.select();document.execCommand("copy");area.remove();toast("Código Pix copiado")}}
function notificationReminder(){if(!("Notification" in window))return `<div class="notification-reminder unavailable"><div><strong>🔔 Acompanhe por esta tela</strong><span>Seu navegador não oferece notificações do site.</span></div></div>`;if(Notification.permission==="granted")return `<div class="notification-reminder enabled"><div><strong>✓ Notificações ativadas</strong><span>Você será avisado quando o pedido mudar de etapa enquanto o site estiver aberto.</span></div></div>`;if(Notification.permission==="denied")return `<div class="notification-reminder unavailable"><div><strong>🔕 Notificações bloqueadas</strong><span>Libere as notificações nas permissões do navegador para receber os avisos.</span></div></div>`;return `<div class="notification-reminder" id="notification-reminder"><div><strong>🔔 Ative as notificações</strong><span>Receba um aviso quando o pedido sair para entrega. Mantenha o site aberto.</span></div><button class="secondary-btn" id="enable-order-notifications">Ativar</button></div>`}
function bindNotificationButton(){const btn=$("#enable-order-notifications");if(btn)btn.onclick=enableOrderNotifications}
async function enableOrderNotifications(){const permission=await Notification.requestPermission();toast(permission==="granted"?"Notificações ativadas":"Não foi possível ativar as notificações");const reminder=$("#notification-reminder");if(reminder)reminder.outerHTML=notificationReminder();bindNotificationButton()}
function notifyOrderStatus(order){if(!("Notification" in window)||Notification.permission!=="granted")return;const items=(order.items||[]).map(i=>`${i.quantity}× ${i.product_name}`).join(", ");const message=order.status==="saiu_entrega"?`O pedido ${order.id} saiu para entrega.${items?` ${items}`:""}`:`O pedido ${order.id} agora está: ${statusLabel(order.status)}.`;try{new Notification("Açailandia PE",{body:message,icon:JW_LOGO,tag:`pedido-${order.id}`,renotify:true})}catch{}}
function beginTracking(code,status){const normalized=String(code||"").trim();if(!normalized)return;if(state.tracking.code!==normalized){clearInterval(state.tracking.timer);state.tracking.timer=null;state.tracking.code=normalized;state.tracking.status=status||null}if(!state.tracking.timer)state.tracking.timer=setInterval(()=>trackOrder(state.tracking.code,true),12000)}

function renderStoreHeader(settings){return `<div class="brand-strip" role="img" aria-label="Banner da Açailandia PE"></div><header class="store-card"><img class="store-logo" src="${JW_LOGO}" alt="Logo Açailandia PE" width="96" height="96" fetchpriority="high"><div><h1 class="store-name">${esc(settings.store_name)}</h1><div class="store-type">Açaiteria</div><div class="store-meta"><span>🛍 Pedido mínimo ${money(settings.minimum_order_cents)}</span><span>🛵 ${esc(eta(settings.delivery_eta))} • taxa conforme bairro</span><span>🏃 ${esc(eta(settings.pickup_eta))}</span></div></div><div class="store-status"><span class="status-pill ${settings.is_open?"":"closed"}"><i class="status-dot"></i>${settings.is_open?`Aberto • até ${esc(settings.closing_time)}`:"Fechado agora"}</span><button class="info-button" data-action="info" aria-label="Informações da loja">i</button></div></header>`}
function promoCard(p){const promoted=p.is_promo&&p.old_price_cents;return `<button class="promo-card" data-product="${p.id}" ${p.is_available?"":"disabled"}><img class="promo-image" src="${esc(p.image_url)}" alt="${esc(p.name)}" loading="lazy" decoding="async" width="360" height="250"><div class="promo-body"><span class="promo-title">${esc(p.name)}</span><span class="promo-desc">${esc(p.description)}</span><span class="prices">${promoted?`<span class="old-price">${money(p.old_price_cents)}</span>`:""}<strong class="price">${money(p.price_cents)}</strong></span></div>${promoted?'<span class="promo-badge">Promoção</span>':""}</button>`}
function productRow(p){const promoted=p.is_promo&&p.old_price_cents;return `<button class="product-row" data-product="${p.id}" ${p.is_available?"":"disabled"}><span class="product-copy"><span class="product-title">${esc(p.name)}</span><span class="product-desc">${esc(p.description)}</span>${p.is_available?`<span class="prices">${promoted?`<span class="old-price">${money(p.old_price_cents)}</span>`:""}<strong class="price">${money(p.price_cents)}</strong></span>`:'<span class="unavailable">Indisponível</span>'}</span><img class="product-thumb" src="${esc(p.image_url)}" alt="" loading="lazy" decoding="async" width="98" height="98"></button>`}
function customerApp(){const {settings,products}=state.catalog;const featured=products.filter(p=>p.is_featured&&p.is_available);const promos=products.filter(p=>p.is_promo&&p.is_available&&p.old_price_cents);const cats=[...new Set(products.map(p=>p.category))],promotionsSection=promos.length?`<section class="section" id="promocoes"><div class="section-head"><h2>Promoções</h2><div class="rail-controls"><span class="section-count">${promos.length} ofertas</span><button data-rail-prev="promocoes" aria-label="Voltar promoções">‹</button><button data-rail-next="promocoes" aria-label="Avançar promoções">›</button></div></div><div class="rail" data-drag-rail>${promos.map(promoCard).join("")}</div></section>`:"";return `<div class="customer-shell">${renderStoreHeader(settings)}<div class="catalog-tools"><div class="tools-inner"><div class="search-row"><label class="search-box">⌕<span class="sr-only">Buscar no cardápio</span><input id="search" placeholder="Buscar açaí, bebida, combo..."></label><button class="cart-top" data-action="cart">Sacola <span class="badge" id="cart-count">${cartCount()}</span></button></div><nav class="chips"><button class="chip active" data-target="destaques">Destaques</button>${promos.length?'<button class="chip" data-target="promocoes">Promoções</button>':""}${cats.map(c=>`<button class="chip" data-target="${slug(c)}">${esc(c)}</button>`).join("")}</nav></div></div><main class="catalog-content"><section class="section" id="destaques"><div class="section-head"><h2>Destaques</h2><div class="rail-controls"><span class="section-count">Produtos mais pedidos</span><button data-rail-prev="destaques" aria-label="Voltar destaques">‹</button><button data-rail-next="destaques" aria-label="Avançar destaques">›</button></div></div><div class="rail" data-drag-rail>${featured.map(promoCard).join("")}</div></section>${promotionsSection}${cats.map(c=>{const list=products.filter(p=>p.category===c);return `<section class="section product-section" id="${slug(c)}" data-category="${esc(c)}"><div class="section-head"><h2>${esc(c)}</h2><span class="section-count">${list.length} ${list.length===1?"item":"itens"}</span></div><div class="product-list">${list.map(productRow).join("")}</div></section>`}).join("")}</main><footer class="customer-footer"><div class="footer-inner"><div class="footer-brand">Açailandia PE</div><div class="footer-grid"><div>Açaiteria<br>${esc(settings.address)}</div><div>Telefone: <a href="tel:${settings.phone.replace(/\D/g,"")}">${esc(settings.phone)}</a><br>© 2026 Açailandia PE</div></div></div></footer></div><nav class="bottom-nav"><button class="nav-item" data-action="track"><span class="nav-icon">▤</span><span>PEDIDOS</span></button><button class="nav-item active" data-action="home"><span class="nav-icon">⌂</span><span>CARDÁPIO</span></button><button class="nav-item" data-action="info"><span class="nav-icon">●</span><span>CONTATO</span></button></nav><div id="layer"></div>`}
function closedStoreApp(){const s=state.catalog.settings,hours=s.business_hours||[];return `<main class="closed-store"><section class="closed-card"><div class="closed-glow"></div><img src="${JW_LOGO}" alt="Logo Açaí Prime"><span class="closed-pill">Loja fechada agora</span><h1>Voltamos no próximo horário de atendimento</h1><p>${esc(s.manual_closed_reason||"No momento não estamos recebendo pedidos pelo site.")}</p><div class="hours-summary"><h2>Horários de funcionamento</h2>${hours.map(day=>`<div class="hours-row ${day.enabled?"":"day-off"}"><span>${esc(day.label)}</span><strong>${day.enabled?`${esc(day.open)} às ${esc(day.close)}`:"Folga"}</strong></div>`).join("")}</div><button class="secondary-btn full" id="closed-info">Ver bairros e taxas de entrega</button><div class="closed-contact">Dúvidas? ${esc(s.phone)}</div></section></main><div id="layer"></div>`}
function applyBlissBrand(){document.querySelectorAll(".footer-brand,.admin-brand strong,.tables-top strong").forEach(el=>el.textContent="Açailandia PE");document.querySelectorAll(".customer-footer").forEach(el=>el.innerHTML=el.innerHTML.replace(/Açaí Prime|Bliss Açaiteria/g,"Açailandia PE"));document.querySelectorAll("img[alt*='Açaí Prime'],img[alt*='Bliss']").forEach(el=>el.alt="Logo Açailandia PE")}
function renderCustomer(){document.title="Açailandia PE — Cardápio";if(!state.catalog.settings.is_open){$("#app").innerHTML=closedStoreApp();applyBlissBrand();$("#closed-info").onclick=openInfo;return}$("#app").innerHTML=customerApp();applyBlissBrand();bindCustomer()}
function bindCustomer(){document.querySelectorAll("[data-product]").forEach(b=>b.onclick=()=>openProduct(Number(b.dataset.product)));document.querySelectorAll("[data-target]").forEach(b=>b.onclick=()=>{$(`#${b.dataset.target}`)?.scrollIntoView({behavior:"smooth",block:"start"});document.querySelectorAll(".chip").forEach(x=>x.classList.toggle("active",x===b))});document.querySelectorAll("[data-rail-prev],[data-rail-next]").forEach(b=>b.onclick=()=>{const id=b.dataset.railPrev||b.dataset.railNext;const rail=$(`#${id} [data-drag-rail]`);rail.scrollBy({left:(b.dataset.railNext?1:-1)*Math.max(280,rail.clientWidth*.72),behavior:"smooth"})});setupDragRails();$("#search").oninput=e=>filterProducts(e.target.value);document.body.onclick=e=>{const a=e.target.closest("[data-action]");if(!a)return;({cart:openCart,info:openInfo,track:openTracking,home:()=>window.scrollTo({top:0,behavior:"smooth"})})[a.dataset.action]?.()}}
function setupDragRails(){document.querySelectorAll("[data-drag-rail]").forEach(rail=>{let active=false,startX=0,startLeft=0,moved=false,pointerId=null;rail.onpointerdown=e=>{if(e.pointerType==="mouse"&&e.button!==0)return;active=true;moved=false;pointerId=e.pointerId;startX=e.clientX;startLeft=rail.scrollLeft};rail.onpointermove=e=>{if(!active)return;const dx=e.clientX-startX;if(!moved&&Math.abs(dx)>10){moved=true;rail.classList.add("dragging");rail.setPointerCapture(pointerId)}if(moved)rail.scrollLeft=startLeft-dx};rail.onpointerup=rail.onpointercancel=()=>{if(!active)return;active=false;rail.classList.remove("dragging");setTimeout(()=>{moved=false},0)};rail.addEventListener("click",e=>{if(!moved)return;e.preventDefault();e.stopPropagation();moved=false},true)})}
function filterProducts(q){const term=q.trim().toLowerCase();document.querySelectorAll("[data-product]").forEach(el=>{const p=state.catalog.products.find(x=>x.id===Number(el.dataset.product));el.classList.toggle("hidden",!!term&&!`${p.name} ${p.description} ${p.category}`.toLowerCase().includes(term))});document.querySelectorAll(".product-section").forEach(s=>s.classList.toggle("hidden",![...s.querySelectorAll("[data-product]")].some(x=>!x.classList.contains("hidden"))))}
function closeLayer(){state.detail=null;state.drawer=null;$("#layer").innerHTML=""}
function layer(content,cls="drawer"){$("#layer").innerHTML=`<div class="overlay" id="overlay"><section class="${cls}" role="dialog" aria-modal="true">${content}</section></div>`;$("#overlay").onclick=e=>{if(e.target.id==="overlay")closeLayer()}}
function acaiGroup(option){const name=String(state.detail?.name||"");if(name.startsWith("Monte seu pote"))return {name:"Complementos grátis",limit:5};if(name.startsWith("Copo trufado")||name.startsWith("Açaí na garrafa"))return {name:"Escolha seu sabor",limit:1};const fruit=["Banana","Manga","Morango","Kiwi"],extras=["Creme de ninho da casa","Creme de oreo da casa","Creme de café","Cupuaçu"];return fruit.includes(option.name)?{name:"Frutas",limit:2}:extras.includes(option.name)?{name:"Extras",limit:3}:{name:"Complementos doces",limit:2}}
function complementGroups(options){const groups=[{title:"Frutas",text:"Escolha até 2 itens",names:["Banana","Manga","Morango","Kiwi"]},{title:"Extras",text:"Escolha até 3 itens",names:["Creme de ninho da casa","Creme de oreo da casa","Creme de café","Cupuaçu"]},{title:"Complementos doces",text:"Escolha até 2 itens",names:[]}];const row=(option,index)=>`<div class="complement-row"><div><strong>${esc(option.name)}</strong><small>${option.price_cents?`+ ${money(option.price_cents)}`:"Sem custo adicional"}</small></div><div class="stepper"><button type="button" data-addon-q="-1" data-addon-index="${index}">−</button><span data-addon-value="${index}">0</span><button type="button" data-addon-q="1" data-addon-index="${index}">+</button></div></div>`;const used=new Set;return groups.map((group,g)=>{const entries=options.map((option,index)=>({option,index})).filter(({option})=>g===2?!groups.slice(0,2).some(x=>x.names.includes(option.name)):group.names.includes(option.name));entries.forEach(({index})=>used.add(index));return entries.length?`<div class="panel-head"><div><strong>${group.title}</strong><div class="muted">${group.text}</div></div></div>${entries.map(({option,index})=>row(option,index)).join("")}`:""}).join("")+options.map((option,index)=>used.has(index)?"":row(option,index)).join("")}
function openProduct(id,cart=state.cart,onAdded=null){const p=state.catalog.products.find(x=>x.id===id);if(!p||!p.is_available)return;state.detail=p;state.detailQty=1;const options=(p.complements||[]).map(option=>({...option,quantity:0})),flavorIncludedInBasePrice=[1,2,10,11].includes(Number(p.id)),price=()=>flavorIncludedInBasePrice?p.price_cents:p.price_cents+options.reduce((sum,option)=>sum+option.price_cents*option.quantity,0);layer(`<div class="drawer-header"><button class="icon-btn" data-close>←</button><h2>PRODUTO</h2></div><div class="detail-body"><h2>${esc(p.name)}</h2><div class="muted">${esc(p.description)}</div>${options.length?`<section class="complements-panel">${complementGroups(options)}</section>`:""}</div><div class="detail-action"><div class="stepper"><button data-q="-1">−</button><span id="detail-qty">1</span><button data-q="1">+</button></div><button class="primary-btn" id="detail-add">Adicionar • <span id="detail-total">${money(p.price_cents)}</span></button></div>`,"product-detail");const refresh=()=>{$("#detail-qty").textContent=state.detailQty;$("#detail-total").textContent=money(price()*state.detailQty)};document.querySelector("[data-close]").onclick=closeLayer;document.querySelectorAll("[data-q]").forEach(b=>b.onclick=()=>{state.detailQty=Math.max(1,Math.min(20,state.detailQty+Number(b.dataset.q)));refresh()});document.querySelectorAll("[data-addon-q]").forEach(b=>b.onclick=()=>{const option=options[Number(b.dataset.addonIndex)],delta=Number(b.dataset.addonQ),group=acaiGroup(option),selected=options.filter(item=>acaiGroup(item).name===group.name).reduce((sum,item)=>sum+item.quantity,0);if(delta>0&&selected>=group.limit)return toast(`${group.name}: limite de ${group.limit} itens`);option.quantity=Math.max(0,Math.min(option.max_quantity,option.quantity+delta));document.querySelector(`[data-addon-value="${b.dataset.addonIndex}"]`).textContent=option.quantity;refresh()});$("#detail-add").onclick=()=>{addItem(p,state.detailQty,cart,options.map(({name,price_cents,quantity})=>({name,price_cents,quantity})).filter(option=>option.quantity));updateCartBadges();closeLayer();if(onAdded)onAdded();toast("Produto adicionado")}}
function updateCartBadges(){document.querySelectorAll("#cart-count").forEach(x=>x.textContent=cartCount())}
function cartItemsMarkup(cart=state.cart){return cart.map(i=>`<div class="cart-item"><img src="${esc(i.product.image_url)}" alt=""><div><div class="cart-name">${esc(i.product.name)}</div>${i.complements?.length?`<div class="cart-addons">${i.complements.map(option=>`+ ${option.quantity}× ${esc(option.name)}`).join("<br>")}</div>`:""}${i.notes?`<div class="cart-note">Obs.: ${esc(i.notes)}</div>`:""}<div class="muted">${money(itemUnitPrice(i)*i.quantity)}</div></div><div class="stepper"><button data-cart-q="-1" data-id="${i.product.id}" data-key="${esc(i.key||i.product.id)}">−</button><span>${i.quantity}</span><button data-cart-q="1" data-id="${i.product.id}" data-key="${esc(i.key||i.product.id)}">+</button></div></div>`).join("")}
function openCart(){layer(`<div class="drawer-header"><button class="icon-btn" data-close>←</button><h2>Sua sacola</h2><button type="button" class="text-danger-btn" id="clear-cart" ${state.cart.length?"":"disabled"}>Limpar</button></div><div class="drawer-content" id="cart-body">${state.cart.length?cartItemsMarkup():'<div class="empty">Sua sacola está vazia.</div>'}</div><div class="drawer-footer"><div class="cart-total"><span>Total</span><span id="cart-total">${money(cartTotal())}</span></div><button class="primary-btn full" id="checkout" ${state.cart.length?"":"disabled"}>Continuar pedido</button></div>`);bindCart()}
function bindCart(){document.querySelector("[data-close]").onclick=closeLayer;document.querySelectorAll("[data-cart-q]").forEach(b=>b.onclick=()=>{updateQty(b.dataset.key,Number(b.dataset.cartQ));openCart();updateCartBadges()});$("#clear-cart").onclick=()=>{state.cart=[];updateCartBadges();openCart();toast("Sacola limpa")};$("#checkout").onclick=openCheckout}
function neighborhoodOptions(city){return `<option value="">Selecione o bairro</option>${(DELIVERY_NEIGHBORHOODS[city]||[]).map(n=>`<option value="${esc(n)}">${esc(n)}</option>`).join("")}`}
function setDeliveryRequired(required){document.querySelectorAll("#address-field [data-delivery-required]").forEach(el=>el.required=required)}
function formatWhatsApp(input){const d=input.value.replace(/\D/g,"").slice(0,11);input.value=d.length>6?`(${d.slice(0,2)}) ${d.slice(2,7)}-${d.slice(7)}`:d.length>2?`(${d.slice(0,2)}) ${d.slice(2)}`:d.length?`(${d}`:"";input.setCustomValidity(d.length===11?"":"Informe um WhatsApp com DDD e 11 números.")}
function useCurrentLocation(){const btn=$("#use-location"),input=$("[name=maps_url]");if(!navigator.geolocation)return toast("Este aparelho não oferece localização.");btn.disabled=true;btn.textContent="Obtendo localização...";navigator.geolocation.getCurrentPosition(pos=>{input.value=`https://www.google.com/maps?q=${pos.coords.latitude.toFixed(6)},${pos.coords.longitude.toFixed(6)}`;input.setCustomValidity("");btn.textContent="✓ Localização confirmada";btn.classList.add("location-ready");btn.disabled=false;toast("Localização adicionada ao pedido")},()=>{btn.disabled=false;btn.textContent="Usar minha localização atual";toast("Permita o acesso à localização ou cole um link do Google Maps.")},{enableHighAccuracy:true,timeout:12000,maximumAge:60000})}
function openCheckout(){state.checkoutType="delivery";state.checkoutFeeCents=0;layer(`<div class="drawer-header"><button class="icon-btn" data-back aria-label="Voltar">←</button><h2>Finalizar pedido</h2></div><div class="drawer-content"><form class="checkout" id="checkout-form"><div class="segmented"><button type="button" class="active" data-type="delivery">Entrega</button><button type="button" data-type="pickup">Retirada</button></div><div class="field"><label>Seu nome *</label><input name="customer_name" required maxlength="80" autocomplete="name"></div><div class="field"><label>WhatsApp com DDD *</label><input name="phone" required inputmode="tel" autocomplete="tel" maxlength="15" placeholder="(87) 99999-9999"></div><fieldset class="delivery-fields" id="address-field"><legend>Endereço de entrega</legend><div class="address-grid city-neighborhood"><div class="field"><label>Cidade *</label><select name="city" data-delivery-required><option value="">Selecione a cidade</option><option value="Petrolina">Petrolina</option></select></div><div class="field"><label>Bairro *</label><input name="neighborhood" data-delivery-required maxlength="100" placeholder="Informe o bairro"></div></div><div class="field"><label>Rua / Avenida *</label><input name="street" data-delivery-required maxlength="160" autocomplete="address-line1" placeholder="Nome da rua ou avenida"></div><div class="address-grid house-details"><div class="field"><label>Número *</label><input name="house_number" data-delivery-required maxlength="20" autocomplete="address-line2" placeholder="Ex.: 60A"></div><div class="field"><label>Bloco <span class="optional">(opcional)</span></label><input name="block" maxlength="40" placeholder="Ex.: B"></div></div><div class="field"><label>Ponto de referência <span class="optional">(opcional)</span></label><input name="reference_point" maxlength="160" placeholder="Ex.: próximo à praça"></div><div class="field"><label>Complemento <span class="optional">(opcional)</span></label><input name="complement" maxlength="120" placeholder="Casa, apartamento, fundos..."></div><div class="field location-field"><label>Localização no Google Maps <span class="optional">(opcional)</span></label><input type="url" name="maps_url" maxlength="500" placeholder="Cole o link do Google Maps"><button type="button" class="secondary-btn location-btn" id="use-location">Usar minha localização atual</button><small>Use somente se quiser facilitar a entrega.</small></div></fieldset><div class="field"><label>Forma de pagamento *</label><select name="payment_method" required><option value="dinheiro">Dinheiro</option><option value="pix">Pix</option><option value="credito">Cartão de crédito</option><option value="debito">Cartão de débito</option></select></div><div class="field"><label>Observações gerais <span class="optional">(opcional)</span></label><textarea name="notes" maxlength="500" placeholder="Alguma informação para a acaiteria?"></textarea></div></form></div><div class="drawer-footer"><div class="subtotal-line"><span>Subtotal</span><span>${money(cartTotal())}</span></div><div class="subtotal-line" id="checkout-fee-row"><span>Taxa de entrega conforme bairro</span><span id="checkout-fee">${money(0)}</span></div><div class="cart-total"><span>Total</span><span id="checkout-total">${money(checkoutTotal())}</span></div><button class="primary-btn full" id="send-order">Enviar pedido</button></div>`);document.querySelector("[data-back]").onclick=openCart;const phone=$("[name=phone]"),neighborhood=$("[name=neighborhood]");phone.oninput=()=>formatWhatsApp(phone);neighborhood.oninput=updateCheckoutFee;$("#use-location").onclick=useCurrentLocation;document.querySelectorAll("[data-type]").forEach(b=>b.onclick=()=>{state.checkoutType=b.dataset.type;document.querySelectorAll("[data-type]").forEach(x=>x.classList.toggle("active",x===b));const delivery=state.checkoutType==="delivery";$("#address-field").classList.toggle("hidden",!delivery);setDeliveryRequired(delivery);$("#checkout-fee-row").classList.toggle("hidden",!delivery);updateCheckoutFee()});$("#send-order").onclick=submitOrder}
async function submitOrder(){const form=$("#checkout-form"),phone=$("[name=phone]");formatWhatsApp(phone);const neighborhoodSearch=$("#neighborhood-search"),neighborhoodValue=$("#neighborhood-value");if(state.checkoutType==="delivery"&&neighborhoodSearch&&neighborhoodValue&&!neighborhoodValue.value.trim())neighborhoodSearch.setCustomValidity("Selecione um bairro da lista para calcular a taxa.");const mapInput=$("[name=maps_url]");mapInput.setCustomValidity(mapInput.value&&!safeMapsUrl(mapInput.value)?"Informe um link válido do Google Maps ou deixe em branco.":"");if(!form.reportValidity())return;const fd=new FormData(form),paymentMethod=fd.get("payment_method"),needsChange=paymentMethod==="dinheiro"&&$("#checkout-needs-change")?.checked,cashValue=$("#checkout-cash-received")?.value||"",cashReceived=Math.max(0,Math.round(Number(String(cashValue).replace(/[^0-9,.-]/g,"").replace(/\./g,"").replace(",","."))*100)||0);if(needsChange&&cashReceived<checkoutTotal())return toast("O valor em dinheiro precisa ser igual ou maior que o total do pedido.");const fdPayload={branch_id:currentBranch(),customer_name:fd.get("customer_name"),phone:fd.get("phone"),city:fd.get("city"),neighborhood:fd.get("neighborhood"),street:fd.get("street"),house_number:fd.get("house_number"),block:fd.get("block"),reference_point:fd.get("reference_point"),complement:fd.get("complement"),maps_url:fd.get("maps_url"),payment_method:paymentMethod,change_for_cents:needsChange?cashReceived-checkoutTotal():null,notes:fd.get("notes"),order_type:state.checkoutType,items:state.cart.map(i=>({product_id:i.product.id,product_name:i.product.name,unit_price_cents:itemUnitPrice(i),quantity:i.quantity,complements:i.complements||[],notes:i.notes||""}))},btn=$("#send-order");btn.disabled=true;btn.textContent="Enviando...";try{const order=await api("/api/orders?branch="+currentBranch(),{method:"POST",body:JSON.stringify(fdPayload)}),completed={...fdPayload,...order,created_at:new Date().toISOString().replace("T"," ").replace("Z","")};state.lastOrder=completed;state.cart=[];updateCartBadges();showSuccess(completed)}catch(e){toast(e.message);btn.disabled=false;btn.textContent="Enviar pedido"}}
function showSuccess(order){rememberOrder(order.id);beginTracking(order.id,order.status);const message=customerOrderMessage(order),storePhone=state.catalog.settings.phone;layer(`<div class="drawer-header"><button class="icon-btn" data-close>×</button><h2>Pedido recebido</h2></div><div class="drawer-content"><div class="success-card"><div class="success-check">✓</div><h2>Agora é com a gente!</h2><p class="muted">Guarde o código para acompanhar o preparo.</p><div class="order-code">${esc(order.id)}</div><div class="timeline"><div class="timeline-row done"><i class="timeline-dot"></i>Pedido recebido</div><div class="timeline-row"><i class="timeline-dot"></i>Confirmação da acaiteria</div><div class="timeline-row"><i class="timeline-dot"></i>Preparo e entrega</div></div></div>${pixPaymentMarkup(order)}<a class="whatsapp-btn full" href="${esc(whatsappUrl(storePhone,message))}" target="_blank" rel="noopener noreferrer"><span class="whatsapp-logo">☎</span><span><strong>Enviar pedido pelo WhatsApp</strong><small>Notifique a acaiteria com o pedido preenchido</small></span></a>${notificationReminder()}</div><div class="drawer-footer"><button class="primary-btn full" data-track="${esc(order.id)}">Acompanhar pedido</button></div>`);document.querySelector("[data-close]").onclick=closeLayer;document.querySelector("[data-track]").onclick=e=>trackOrder(e.currentTarget.dataset.track);bindNotificationButton()}
function openTracking(){layer(`<div class="drawer-header"><button class="icon-btn" data-close>←</button><h2>Acompanhar pedido</h2></div><div class="drawer-content"><div class="field"><label>Código do pedido</label><input id="track-code" value="${esc(state.lastOrder?.id||"")}" placeholder="PED-..."></div><button class="primary-btn full" id="track-go">Consultar</button>${notificationReminder()}<div id="track-result"></div></div>`);document.querySelector("[data-close]").onclick=closeLayer;$("#track-go").onclick=()=>trackOrder($("#track-code").value);bindNotificationButton();if(state.lastOrder?.id)trackOrder(state.lastOrder.id)}
function trackingMarkup(o){const steps=o.order_type==="delivery"?["novo","confirmado","preparando","pronto","saiu_entrega","concluido"]:["novo","confirmado","preparando","pronto","concluido"];const at=steps.indexOf(o.status);const cancelled=o.status==="cancelado";return `<div class="panel tracking-card"><div class="tracking-head"><div><strong>${esc(o.id)}</strong><span>${esc(orderTypeLabel(o.order_type))}</span></div><strong>${money(o.total_cents)}</strong></div>${cancelled?`<div class="tracking-cancelled"><strong>Pedido cancelado.</strong>${o.cancel_reason?`<span>Motivo: ${esc(o.cancel_reason)}</span>`:`<span>Entre em contato com a acaiteria se precisar de ajuda.</span>`}</div>`:`<div class="timeline">${steps.map((s,i)=>`<div class="timeline-row ${i<=at?"done":""} ${s==="saiu_entrega"&&o.status==="saiu_entrega"?"current":""}"><i class="timeline-dot"></i><span>${statusLabel(s)}</span>${s==="saiu_entrega"&&o.status==="saiu_entrega"?"<strong>Seu pedido está a caminho!</strong>":""}</div>`).join("")}</div>`}<div class="tracking-items">${(o.items||[]).map(i=>`<span>${i.quantity}× ${esc(i.product_name)}</span>`).join("")}</div><small class="tracking-refresh">Atualização automática a cada 12 segundos</small></div>`}
async function trackOrder(code,background=false){if(!code){if(!background)toast("Informe o código do pedido");return}const normalized=String(code).trim();try{const o=await api(`/api/orders/${encodeURIComponent(normalized)}`);const previous=state.tracking.code===normalized?state.tracking.status:null;if(previous&&previous!==o.status)notifyOrderStatus(o);rememberOrder(o.id);beginTracking(o.id,o.status);state.tracking.status=o.status;if(!background&&!$("#track-result"))openTracking();if($("#track-result"))$("#track-result").innerHTML=trackingMarkup(o)}catch(e){if(!background)toast(e.message)}}
function openInfo(){const s=state.catalog.settings,rules=s.delivery_neighborhood_fees||[],fees=rules.length?`<div class="delivery-fee-public">${rules.map(rule=>`<div><span>${esc(rule.city)} • ${esc(rule.neighborhood)}</span><strong>${money(rule.fee_cents)}</strong></div>`).join("")}</div>`:'<p class="muted">Nenhuma taxa cadastrada no momento.</p>';layer(`<div class="drawer-header"><button class="icon-btn" data-close>←</button><h2>Bliss Açaiteria</h2></div><div class="drawer-content"><img class="store-logo" style="margin-bottom:18px" src="${JW_LOGO}" alt=""><h2>Informações da loja</h2><p><strong>Endereço</strong><br>${esc(s.address)}</p><p><strong>Telefone</strong><br><a href="tel:${s.phone.replace(/\D/g,"")}">${esc(s.phone)}</a></p><p><strong>Entrega</strong><br>${esc(eta(s.delivery_eta))} • confira as taxas antes de pedir</p>${s.delivery_surcharge_enabled?`<div class="fee-alert">${esc(s.delivery_surcharge_label||"Acréscimo temporário")} • +${Number(s.delivery_surcharge_percent||0)}%</div>`:""}<h3>Bairros e taxas de entrega</h3>${fees}<p><strong>Retirada</strong><br>${esc(eta(s.pickup_eta))}</p></div>`);document.querySelector("[data-close]").onclick=closeLayer}

function tableStatusLabel(status){return({novo:"Aguardando",confirmado:"Confirmado",preparando:"Em preparo",pronto:"Pronto",saiu_entrega:"Em atendimento"})[status]||"Ocupada"}
function tablesBoardMarkup(data,{admin=false}={}){const tables=data?.tables||[];return `<div class="tables-summary"><div><strong>${data?.available_count||0}</strong><span>Disponíveis</span></div><div><strong>${data?.occupied_count||0}</strong><span>Ocupadas</span></div><div><strong>${data?.table_count||0}</strong><span>Total de mesas</span></div></div>${tables.length?`<div class="tables-grid">${tables.map(table=>{const content=`<span class="table-dot"></span><strong>Mesa ${table.number}</strong><span>${table.occupied?tableStatusLabel(table.status):"Disponível"}</span>${admin&&table.occupied?`<small>${esc(table.order_id)}</small>`:""}`;return admin&&table.occupied?`<button type="button" class="table-card table-card-action occupied" data-table-order="${esc(table.order_id)}" aria-label="Abrir pedido da mesa ${table.number}">${content}</button>`:`<article class="table-card ${table.occupied?"occupied":"available"}">${content}</article>`}).join("")}</div>`:`<div class="empty table-empty">O proprietário ainda não configurou a quantidade de mesas.</div>`}`}
function publicTablesApp(){const data=state.tables.data;return `<main class="public-tables"><header class="tables-top"><img src="${JW_LOGO}" alt="Bliss Açaiteria"><div><strong>Bliss Açaiteria</strong><span>Painel de mesas</span></div><a href="/">Cardápio</a></header><section class="tables-hero"><div><span class="eyebrow">ATUALIZAÇÃO AO VIVO</span><h1>Mesas da casa</h1><p>Consulte quais mesas estão disponíveis antes de fazer seu pedido.</p></div><span class="tables-clock" id="tables-clock">${new Date().toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"})}</span></section>${tablesBoardMarkup(data)}</main>`}
async function loadPublicTables(){state.tables.data=await api("/api/tables");if(location.pathname==="/mesas"){$("#app").innerHTML=publicTablesApp()}}
function startPublicTables(){document.title="Bliss Açaiteria — Mesas";loadPublicTables().catch(e=>{$("#app").innerHTML=`<div class="boot"><div class="boot-mark">!</div><h2>Não foi possível carregar as mesas</h2><p>${esc(e.message)}</p><button class="primary-btn" onclick="location.reload()">Tentar novamente</button></div>`});clearInterval(state.tables.timer);state.tables.timer=setInterval(()=>loadPublicTables().catch(()=>{}),10000)}

// Painel do proprietário
function adminLayout(content,title){return `<div class="admin-shell"><aside class="admin-side"><div class="admin-brand"><img src="${JW_LOGO}" alt="Logo Bliss Açaiteria"><div><strong>Bliss Açaiteria</strong><span>Gestão do negócio</span></div></div><nav class="admin-nav">${adminNavButtons()}</nav><div class="admin-side-footer"><button class="secondary-btn full" data-admin-action="open-store">Ver cardápio público</button></div></aside><main class="admin-main"><header class="admin-topbar"><h1>${esc(title)}</h1><div class="admin-top-actions"><span class="live-pill">● Sistema online</span><button class="secondary-btn" data-admin-action="logout">Sair</button></div></header><div class="admin-content">${content}</div></main><nav class="admin-mobile-nav">${adminNavButtons()}</nav></div><div id="layer"></div>`}
function adminNavButtons(){return [{v:"orders",i:"▤",l:"Pedidos",s:"Pedidos"},{v:"pos",i:"＋",l:"Balcão",s:"Balcão"},{v:"availability",i:"◷",l:"Abrir / fechar",s:"Loja"},{v:"tables",i:"▦",l:"Mesas",s:"Mesas"},{v:"revenue",i:"▥",l:"Faturamento",s:"Fatur."},{v:"products",i:"▤",l:"Produtos",s:"Produtos"},{v:"settings",i:"⚙",l:"Configurações",s:"Config."}].map(x=>`<button class="${state.admin.view===x.v?"active":""}" data-admin-view="${x.v}"><span class="admin-nav-icon">${x.i}</span><span class="nav-full">${x.l}</span><span class="nav-short">${x.s}</span></button>`).join("")}
function loginPage(){return `<div class="login-page"><form class="login-card" id="login-form"><img class="login-logo" src="${JW_LOGO}" alt="Logo Açailandia PE"><h1>Painel da Açailandia PE</h1><p>Digite o PIN administrativo para gerenciar pedidos, cardápio e vendas no balcão.</p><label class="sr-only" for="pin">PIN</label><input class="pin-input" id="pin" name="pin" maxlength="32" autocomplete="current-password" placeholder="Digite o PIN"><button class="primary-btn full">Entrar no painel</button></form></div>`}
async function startAdmin(){document.title="Açailandia PE — Gestão";try{const data=await api("/api/admin/orders");state.admin.logged=true;state.admin.orders=data.orders;state.admin.visits=data.visits||{today:0,total:0};renderAdmin();startAdminRefresh()}catch{$("#app").innerHTML=loginPage();$("#login-form").onsubmit=adminLogin}}
async function adminLogin(e){e.preventDefault();const btn=e.currentTarget.querySelector("button");btn.disabled=true;try{await api("/api/admin/login",{method:"POST",body:JSON.stringify({pin:$("#pin").value})});state.admin.logged=true;await loadAdminOrders();renderAdmin();startAdminRefresh()}catch(err){toast(err.message);btn.disabled=false}}
function startAdminRefresh(){clearInterval(state.admin.refresh);state.admin.refresh=setInterval(async()=>{if(state.admin.logged&&state.admin.view==="orders"&&!$("#overlay")){await loadAdminOrders().catch(()=>{});renderAdmin()}},15000)}
async function loadAdminOrders(){state.admin.orders=(await api("/api/admin/orders")).orders}
function orderStats(){const today=brazilDateKey();const orders=state.admin.orders.filter(o=>!o.created_at||brazilDateKey(o.created_at)===today);return {count:orders.length,revenue:orders.filter(o=>o.status!=="cancelado").reduce((s,o)=>s+o.total_cents,0),online:orders.filter(o=>o.channel==="online").length,counter:orders.filter(o=>o.channel==="counter").length}}
function renderAdmin(){let title="Pedidos";let content="";if(state.admin.view==="orders")content=ordersView();if(state.admin.view==="pos"){title="Novo pedido no balcão";content=posView()}if(state.admin.view==="availability"){title="Abrir ou fechar a loja";content=availabilityView()}if(state.admin.view==="tables"){title="Controle de mesas";content=tablesView()}if(state.admin.view==="revenue"){title="Faturamento";content=revenueView()}if(state.admin.view==="products"){title="Produtos";content=productsView()}if(state.admin.view==="settings"){title="Configurações";content=settingsView()}$("#app").innerHTML=adminLayout(content,title);applyBlissBrand();bindAdmin();if(state.admin.view==="settings")setupTableSettings()}
function ordersView(){const st=orderStats();const groups=[{title:"Novos",s:["novo"]},{title:"Em produção",s:["confirmado","preparando"]},{title:"Prontos",s:["pronto"]},{title:"Saiu para entrega",s:["saiu_entrega"],delivery:true},{title:"Finalizados",s:["concluido","cancelado"]}];const filtered=state.admin.orderFilter==="all"?state.admin.orders:state.admin.orders.filter(o=>o.channel===state.admin.orderFilter);return `<div class="stat-grid"><div class="stat"><div class="stat-label">Pedidos hoje</div><div class="stat-value">${st.count}</div></div><div class="stat"><div class="stat-label">Vendas hoje</div><div class="stat-value">${money(st.revenue)}</div></div><div class="stat"><div class="stat-label">Via site</div><div class="stat-value">${st.online}</div></div><div class="stat"><div class="stat-label">Balcão</div><div class="stat-value">${st.counter}</div></div></div><div class="view-toolbar"><div class="filter-tabs"><button class="${state.admin.orderFilter==="all"?"active":""}" data-order-filter="all">Todos</button><button class="${state.admin.orderFilter==="online"?"active":""}" data-order-filter="online">Delivery / site</button><button class="${state.admin.orderFilter==="counter"?"active":""}" data-order-filter="counter">Local / balcão</button></div><span class="muted">Atualização automática a cada 15 segundos</span></div><div class="order-board">${groups.map(g=>{const list=filtered.filter(o=>g.s.includes(o.status)&&(!g.delivery||o.order_type==="delivery"));return `<section class="order-column ${g.delivery?"delivery-column":""}"><h2 class="column-title">${g.title}<span class="column-count">${list.length}</span></h2>${list.length?list.map(orderCard).join(""):'<div class="empty panel">Nenhum pedido aqui.</div>'}</section>`}).join("")}</div>`}
function orderCard(o){const statuses=["novo","confirmado","preparando","pronto","saiu_entrega","concluido"];const cancelled=o.status==="cancelado";return `<article class="order-card ${o.channel}" data-order-details="${esc(o.id)}" tabindex="0" role="button" aria-label="Ver todos os detalhes do pedido ${esc(o.id)}"><div class="order-card-head"><span class="order-id">${esc(o.id)}</span><span class="order-time">${new Date(o.created_at+"Z").toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"})}</span></div><div class="source-tag ${o.channel}">${o.channel==="online"?"DELIVERY • SITE":"LOCAL • BALCÃO"}</div><div class="order-customer">${esc(o.customer_name||"Cliente")}</div><div class="order-meta">${o.order_type==="delivery"?"Entrega":"Retirada"}${o.table_number?` • Mesa ${o.table_number}`:""}${o.phone?` • ${esc(o.phone)}`:""}</div>${orderAddressMarkup(o)}<div class="order-lines">${o.items.map(i=>`<div class="order-line"><span>${i.quantity}× ${esc(i.product_name)}</span><span>${money(i.quantity*i.unit_price_cents)}</span></div>`).join("")}</div>${o.delivery_fee_cents?`<div class="order-line fee-line"><span>Taxa de entrega</span><span>${money(o.delivery_fee_cents)}</span></div>`:""}${o.waiter_fee_cents?`<div class="order-line fee-line"><span>Taxa de garçom</span><span>${money(o.waiter_fee_cents)}</span></div>`:""}<div class="order-meta payment-meta">${paymentLabel(o.payment_method)} • <strong>${o.payment_status==="aberto"?"EM ABERTO":"PAGO"}</strong></div><div class="order-total"><span>Total</span><span>${money(o.total_cents)}</span></div>${cancelled?`<div class="order-cancel-reason"><strong>Cancelado</strong><span>${esc(o.cancel_reason||"Motivo não informado")}</span></div>`:`<select class="status-select" data-status-id="${esc(o.id)}">${statuses.map(s=>`<option value="${s}" ${s===o.status?"selected":""}>${statusLabel(s)}</option>`).join("")}</select>`}<div class="order-actions"><button class="secondary-btn compact" data-payment-order="${esc(o.id)}">${o.payment_status==="aberto"?"Marcar pago":"Deixar em aberto"}</button><button class="secondary-btn compact" data-edit-order="${esc(o.id)}" ${cancelled?"disabled":""}>Editar</button><button class="danger-btn compact" data-cancel-order="${esc(o.id)}" ${cancelled?"disabled":""}>Cancelar</button></div><span class="order-card-hint">Ver todos os detalhes →</span></article>`}
function orderDetailAddress(o){const map=safeMapsUrl(o.maps_url);if(o.order_type!=="delivery")return `<div class="detail-empty">Pedido para retirada no balcão.</div>`;const hasAddress=o.city||o.address;return `<div class="detail-address">${hasAddress?(o.city?`<div><span>Rua</span><strong>${esc(o.street||"Não informada")}</strong></div><div><span>Número</span><strong>${esc(o.house_number||"Não informado")}${o.block?` • Bloco ${esc(o.block)}`:""}</strong></div><div><span>Bairro</span><strong>${esc(o.neighborhood||"Não informado")}</strong></div><div><span>Cidade</span><strong>${esc(o.city||"Não informada")}</strong></div><div class="detail-wide"><span>Ponto de referência</span><strong>${esc(o.reference_point||"Não informado")}</strong></div>${o.complement?`<div class="detail-wide"><span>Complemento</span><strong>${esc(o.complement)}</strong></div>`:""}`:`<div class="detail-wide"><span>Endereço</span><strong>${esc(o.address)}</strong></div>`):'<div class="detail-empty">Localização não informada.</div>'}${map?`<a class="maps-detail-btn" href="${esc(map)}" target="_blank" rel="noopener noreferrer">⌖ Abrir localização no Google Maps</a>`:""}</div>`}
function openOrderDetails(id){const o=state.admin.orders.find(order=>order.id===id);if(!o)return;const cancelled=o.status==="cancelado",digits=String(o.phone||"").replace(/\D/g,""),whatsapp=digits.length>=10?`https://wa.me/${digits.startsWith("55")?digits:`55${digits}`}`:"";layer(`<div class="drawer-header"><button class="icon-btn" data-close>×</button><div><h2>Detalhes do pedido</h2><span class="muted">${esc(o.id)}</span></div></div><div class="drawer-content order-detail-content"><div class="detail-hero-row"><span class="source-tag ${o.channel}">${o.channel==="online"?"DELIVERY • SITE":"LOCAL • BALCÃO"}</span><span class="detail-status ${o.status}">${statusLabel(o.status)}</span></div><section class="detail-section"><h3>Cliente</h3><div class="detail-grid"><div><span>Nome</span><strong>${esc(o.customer_name||"Cliente")}</strong></div><div><span>WhatsApp</span>${whatsapp?`<a href="${esc(whatsapp)}" target="_blank" rel="noopener noreferrer">${esc(o.phone)}</a>`:`<strong>Não informado</strong>`}</div><div><span>Tipo do pedido</span><strong>${o.order_type==="delivery"?"Entrega":"Retirada"}</strong></div><div><span>Recebido em</span><strong>${new Date(o.created_at+"Z").toLocaleString("pt-BR",{dateStyle:"short",timeStyle:"short"})}</strong></div></div></section><section class="detail-section"><h3>Endereço e localização</h3>${orderDetailAddress(o)}</section><section class="detail-section"><h3>Itens do pedido</h3><div class="detail-items">${o.items.map(i=>`<div><span><b>${i.quantity}×</b> ${esc(i.product_name)}</span><strong>${money(i.quantity*i.unit_price_cents)}</strong></div>`).join("")}</div><div class="detail-totals"><div><span>Subtotal</span><strong>${money(o.subtotal_cents||o.total_cents-(o.waiter_fee_cents||0))}</strong></div>${o.delivery_fee_cents?`<div><span>Taxa de entrega</span><strong>${money(o.delivery_fee_cents)}</strong></div>`:""}${o.waiter_fee_cents?`<div><span>Taxa de garçom</span><strong>${money(o.waiter_fee_cents)}</strong></div>`:""}<div class="detail-grand-total"><span>Total</span><strong>${money(o.total_cents)}</strong></div></div></section><section class="detail-section"><h3>Pagamento e observações</h3><div class="detail-grid"><div><span>Forma de pagamento</span><strong>${paymentLabel(o.payment_method)}</strong></div><div><span>Situação do pagamento</span><strong>${o.payment_status==="aberto"?"Em aberto":"Pago"}</strong></div>${o.change_for_cents?`<div><span>Troco para</span><strong>${money(o.change_for_cents)}</strong></div>`:""}<div class="detail-wide"><span>Observações gerais</span><strong>${esc(o.notes||"Sem observações")}</strong></div></div></section>${cancelled?`<section class="detail-section detail-cancelled"><h3>Motivo do cancelamento</h3><p>${esc(o.cancel_reason||"Motivo não informado")}</p></section>`:""}</div><div class="drawer-footer order-detail-actions"><button class="secondary-btn" id="detail-edit-order" ${cancelled?"disabled":""}>Editar pedido</button><button class="danger-btn" id="detail-cancel-order" ${cancelled?"disabled":""}>Cancelar pedido</button></div>`,"drawer admin-order-drawer");document.querySelector("[data-close]").onclick=closeLayer;$("#detail-edit-order").onclick=()=>openOrderEditor(id);$("#detail-cancel-order").onclick=()=>openCancelOrder(id)}
async function openOrderEditor(id){const order=state.admin.orders.find(o=>o.id===id);if(!order)return;if(!state.catalog)state.catalog=await api("/api/admin/products");state.admin.editOrderId=id;state.admin.editOrderCart=order.items.map(item=>{const product=state.catalog.products.find(p=>p.id===item.product_id)||{id:item.product_id,name:item.product_name,image_url:JW_LOGO,price_cents:item.unit_price_cents};let complements=[];try{complements=JSON.parse(item.complements_json||"[]")}catch{}const notes=item.notes||"",key=cartItemKey(product,complements,notes);return {product,quantity:item.quantity,unit_price_cents:item.unit_price_cents,complements,notes,key}});renderOrderEditor()}
function editOrderTotals(){const order=state.admin.orders.find(o=>o.id===state.admin.editOrderId),subtotal=cartTotal(state.admin.editOrderCart),fee=order?.waiter_fee_cents&&order?.subtotal_cents?Math.round(subtotal*order.waiter_fee_cents/order.subtotal_cents):0;return {subtotal,fee,deliveryFee:order?.delivery_fee_cents||0,total:subtotal+fee+(order?.delivery_fee_cents||0)}}
function renderOrderEditor(){const order=state.admin.orders.find(o=>o.id===state.admin.editOrderId);if(!order)return;const totals=editOrderTotals(),products=state.catalog.products.filter(p=>p.is_available);layer(`<div class="drawer-header"><button class="icon-btn" data-close>×</button><div><h2>Editar pedido</h2><span class="muted">${esc(order.id)}${order.channel==="online"?" • alteração visível para o cliente":""}</span></div></div><div class="drawer-content order-editor"><section><strong>Itens do pedido</strong><div class="edit-order-items">${state.admin.editOrderCart.length?cartItemsMarkup(state.admin.editOrderCart):'<div class="empty">O pedido precisa ter pelo menos um produto.</div>'}</div></section><section><div class="field"><label>Adicionar produto</label><input id="edit-order-search" placeholder="Buscar no cardápio"></div><div class="edit-product-picker">${products.map(p=>`<button class="edit-product-option" data-order-add="${p.id}"><img src="${esc(p.image_url)}" alt=""><span><strong>${esc(p.name)}</strong><small>${money(p.price_cents)}</small></span><b>＋</b></button>`).join("")}</div></section></div><div class="drawer-footer"><div class="subtotal-line"><span>Subtotal</span><span>${money(totals.subtotal)}</span></div>${totals.deliveryFee?`<div class="subtotal-line"><span>Taxa de entrega</span><span>${money(totals.deliveryFee)}</span></div>`:""}${totals.fee?`<div class="subtotal-line"><span>Taxa de garçom</span><span>${money(totals.fee)}</span></div>`:""}<div class="cart-total"><span>Novo total</span><span>${money(totals.total)}</span></div><button class="primary-btn full" id="save-order-edit" ${state.admin.editOrderCart.length?"":"disabled"}>Salvar alterações</button></div>`,"drawer admin-order-drawer");document.querySelector("[data-close]").onclick=closeLayer;document.querySelectorAll("[data-cart-q]").forEach(b=>b.onclick=()=>{updateQty(Number(b.dataset.id),Number(b.dataset.cartQ),state.admin.editOrderCart);renderOrderEditor()});document.querySelectorAll("[data-order-add]").forEach(b=>b.onclick=()=>{const p=state.catalog.products.find(x=>x.id===Number(b.dataset.orderAdd));addItem(p,1,state.admin.editOrderCart);renderOrderEditor()});$("#edit-order-search").oninput=e=>{const q=e.target.value.toLowerCase();document.querySelectorAll("[data-order-add]").forEach(b=>{const p=state.catalog.products.find(x=>x.id===Number(b.dataset.orderAdd));b.classList.toggle("hidden",!p.name.toLowerCase().includes(q))})};$("#save-order-edit").onclick=saveOrderEdit}
async function saveOrderEdit(){const btn=$("#save-order-edit");btn.disabled=true;try{await api(`/api/admin/orders/${encodeURIComponent(state.admin.editOrderId)}/items`,{method:"PATCH",body:JSON.stringify({items:state.admin.editOrderCart.map(i=>({product_id:i.product.id,quantity:i.quantity,complements:i.complements||[],notes:i.notes||""}))})});await loadAdminOrders();closeLayer();renderAdmin();toast("Pedido atualizado para a acaiteria e para o cliente")}catch(e){toast(e.message);btn.disabled=false}}
function openCancelOrder(id){const order=state.admin.orders.find(o=>o.id===id);if(!order)return;layer(`<div class="drawer-header"><button class="icon-btn" data-close>×</button><h2>Cancelar pedido</h2></div><form class="drawer-content cancel-order-form" id="cancel-order-form"><p>Informe por que o pedido <strong>${esc(order.id)}</strong> será cancelado. O motivo ficará visível para o cliente quando o pedido tiver sido feito pelo site.</p><div class="field"><label>Motivo do cancelamento</label><textarea name="reason" maxlength="500" required placeholder="Ex.: Produto indisponível, solicitação do cliente..."></textarea></div></form><div class="drawer-footer"><button class="danger-btn full" id="confirm-cancel-order">Confirmar cancelamento</button></div>`,"drawer admin-order-drawer");document.querySelector("[data-close]").onclick=closeLayer;$("#confirm-cancel-order").onclick=()=>cancelOrder(id)}
async function cancelOrder(id){const form=$("#cancel-order-form");if(!form.reportValidity())return;const btn=$("#confirm-cancel-order");btn.disabled=true;try{await api(`/api/admin/orders/${encodeURIComponent(id)}/cancel`,{method:"PATCH",body:JSON.stringify({reason:new FormData(form).get("reason")})});await loadAdminOrders();closeLayer();renderAdmin();toast("Pedido cancelado")}catch(e){toast(e.message);btn.disabled=false}}
function posGrandTotal(){const subtotal=cartTotal(state.admin.posCart);return subtotal+(state.admin.posWaiterFee&&state.catalog.settings.waiter_fee_enabled?Math.round(subtotal*state.catalog.settings.waiter_fee_percent/100):0)}
function tablesView(){const data=state.admin.tables;return `<section class="tables-admin"><div class="panel-head table-panel-head"><div><h2>Visão das mesas</h2><span class="muted">Uma mesa é liberada automaticamente quando o pedido é concluído ou cancelado.</span></div><a class="secondary-btn" href="/mesas" target="_blank" rel="noopener noreferrer">Abrir painel para telão</a></div>${tablesBoardMarkup(data,{admin:true})}</section>`}
function posView(){const products=state.catalog.products.filter(p=>p.is_available),s=state.catalog.settings,fee=Math.round(cartTotal(state.admin.posCart)*(s.waiter_fee_percent||0)/100),tables=state.admin.tables?.tables||[],available=tables.filter(table=>!table.occupied);return `<div class="pos-layout"><section class="pos-catalog"><div class="panel-head" style="padding:0 0 14px;border:0"><div><strong>Cardápio rápido</strong><div class="muted">Toque nos produtos para adicionar</div></div><input class="admin-price-input" id="pos-search" placeholder="Buscar produto"></div><div class="pos-products" id="pos-products">${products.map(p=>`<button class="pos-product" data-pos-add="${p.id}"><img src="${esc(p.image_url)}" alt=""><strong>${esc(p.name)}</strong><span>${money(p.price_cents)}</span></button>`).join("")}</div></section><aside class="panel pos-cart"><div class="panel-head"><h2>Pedido presencial</h2><strong id="pos-count">${cartCount(state.admin.posCart)} itens</strong></div><div class="pos-cart-body" id="pos-cart-body">${state.admin.posCart.length?cartItemsMarkup(state.admin.posCart):'<div class="empty">Adicione produtos ao pedido.</div>'}</div><form class="pos-form" id="pos-form"><div class="field"><label>Cliente</label><input name="customer_name" placeholder="Ex.: João"></div><div class="field" id="pos-table-field"><label>Mesa *</label><select name="table_number" required ${available.length?"":"disabled"}><option value="">${available.length?"Selecione uma mesa disponível":"Não há mesas disponíveis"}</option>${available.map(table=>`<option value="${table.number}">Mesa ${table.number}</option>`).join("")}</select><small>${state.admin.tables?.table_count?`${available.length} mesa(s) disponível(is)`:'Configure a quantidade de mesas em Configurações.'}</small></div><div class="compact-field"><div class="field"><label>Tipo</label><select name="order_type"><option value="pickup">Consumir no local</option><option value="delivery">Entrega</option></select></div><div class="field"><label>Pagamento</label><select name="payment_method"><option value="dinheiro">Dinheiro</option><option value="pix">Pix</option><option value="credito">Cartão de crédito</option><option value="debito">Cartão de débito</option></select></div><div class="field"><label>Situação</label><select name="payment_status"><option value="pago">Pago</option><option value="aberto">Pagamento em aberto</option></select></div></div>${s.waiter_fee_enabled?`<label class="check-row"><input type="checkbox" id="pos-waiter-fee" ${state.admin.posWaiterFee?"checked":""}><span><strong>Adicionar taxa de garçom (${s.waiter_fee_percent}%)</strong><small>Opcional • ${money(fee)}</small></span></label>`:""}<div class="field"><label>Observações</label><input name="notes" placeholder="Sem cebola, aniversariante..."></div></form><div class="pos-footer"><div class="subtotal-line"><span>Subtotal</span><span>${money(cartTotal(state.admin.posCart))}</span></div>${state.admin.posWaiterFee?`<div class="subtotal-line"><span>Taxa de garçom</span><span>${money(fee)}</span></div>`:""}<div class="cart-total"><span>Total</span><span id="pos-total">${money(posGrandTotal())}</span></div><button class="primary-btn full" id="pos-finish" ${state.admin.posCart.length&&available.length?"":"disabled"}>Registrar pedido</button></div></aside></div>`}
function productsView(){const categories=state.catalog.categories||[...new Set(state.catalog.products.map(product=>product.category))];return `<section class="panel category-order-panel"><div class="panel-head"><div><h2>Ordem das categorias</h2><span class="muted">Use as setas para definir a ordem exibida no cardápio do cliente.</span></div></div><div class="category-order-list">${categories.map((category,index)=>`<div class="category-order-row"><b>${index+1}</b><span>${esc(category)}</span><button class="icon-btn" data-category-move="up" data-category-index="${index}" ${index===0?"disabled":""}>↑</button><button class="icon-btn" data-category-move="down" data-category-index="${index}" ${index===categories.length-1?"disabled":""}>↓</button></div>`).join("")}</div></section><section class="panel"><div class="panel-head"><div><h2>Cardápio</h2><span class="muted">Os 8 produtos mais pedidos aparecem automaticamente em Destaques.</span></div><button class="primary-btn" id="new-product">＋ Cadastrar produto</button></div><div class="product-admin-list">${state.catalog.products.map(p=>`<div class="product-admin-row"><img src="${esc(p.image_url)}" alt=""><div><strong>${esc(p.name)}</strong><div class="muted">${esc(p.description)}</div></div><div class="admin-category muted">${esc(p.category)}</div><label class="admin-price-wrap"><span class="sr-only">Preço</span><input class="admin-price-input" data-price-id="${p.id}" inputmode="decimal" value="${(p.price_cents/100).toFixed(2).replace(".",",")}"></label><div class="product-actions"><button class="secondary-btn compact" data-edit-product="${p.id}">Editar</button><button class="switch ${p.is_available?"on":""}" data-toggle-id="${p.id}" aria-label="Alternar disponibilidade"></button></div></div>`).join("")}</div></section>`}
function complementEditorRow(option={name:"",price_cents:0,max_quantity:1}){return `<div class="admin-complement-row"><div class="field"><label>Complemento</label><input data-complement-name maxlength="80" value="${esc(option.name)}" placeholder="Ex.: Adicional bacon"></div><div class="field"><label>Preço (R$)</label><input data-complement-price inputmode="decimal" value="${(Number(option.price_cents||0)/100).toFixed(2).replace(".",",")}"></div><div class="field"><label>Limite</label><input data-complement-max type="number" min="1" max="20" value="${Number(option.max_quantity||1)}"></div><button type="button" class="icon-btn remove-complement" aria-label="Remover complemento">×</button></div>`}
function productEditor(product){const p=product||{name:"",description:"",category:"",price_cents:0,image_url:"",is_available:true,is_promo:false,complements:[]};const cats=state.catalog.categories||[...new Set(state.catalog.products.map(x=>x.category))];return `<div class="drawer-header"><button class="icon-btn" data-close>×</button><h2>${product?"Editar produto":"Cadastrar produto"}</h2></div><form class="drawer-content product-form" id="product-form"><div class="image-picker"><img id="product-preview" src="${esc(p.image_url||JW_LOGO)}" alt="Prévia da imagem"><label class="secondary-btn">Escolher imagem<input type="file" name="image" id="product-image" accept="image/jpeg,image/png,image/webp" hidden></label><small>JPG, PNG ou WebP • até 3 MB</small></div><div class="field"><label>Nome do produto</label><input name="name" maxlength="120" required value="${esc(p.name)}"></div><div class="field"><label>Valor (R$)</label><input name="price" inputmode="decimal" required value="${p.price_cents?(p.price_cents/100).toFixed(2).replace(".",","):""}"></div><div class="field"><label>Descrição</label><textarea name="description" maxlength="500" placeholder="Ingredientes ou detalhes do produto">${esc(p.description)}</textarea></div><div class="field"><label>Categoria</label><input name="category" list="category-options" maxlength="80" required value="${esc(p.category)}"><datalist id="category-options">${cats.map(c=>`<option value="${esc(c)}">`).join("")}</datalist></div><section class="complement-editor"><div class="panel-head"><div><strong>Complementos deste produto</strong><div class="muted">Deixe vazio para bebidas ou produtos sem adicionais.</div></div><button type="button" class="secondary-btn compact" id="add-product-complement">＋ Adicionar</button></div><div id="product-complements">${(p.complements||[]).map(complementEditorRow).join("")}</div></section><div class="checks-grid"><label class="check-row"><input type="checkbox" name="is_available" ${p.is_available?"checked":""}><span>Disponível</span></label><label class="check-row"><input type="checkbox" name="is_promo" ${p.is_promo?"checked":""}><span>Promoção</span></label></div></form><div class="drawer-footer"><button class="primary-btn full" id="save-product">${product?"Salvar alterações":"Cadastrar produto"}</button></div>`}
function bindComplementEditor(){const list=$("#product-complements");$("#add-product-complement").onclick=()=>{list.insertAdjacentHTML("beforeend",complementEditorRow());bindComplementRemovers()};function bindComplementRemovers(){document.querySelectorAll(".remove-complement").forEach(button=>button.onclick=()=>button.closest(".admin-complement-row").remove())}bindComplementRemovers()}
function openProductEditor(id){const product=id?state.catalog.products.find(p=>p.id===id):null;layer(productEditor(product),"drawer admin-product-drawer");document.querySelector("[data-close]").onclick=closeLayer;$("#product-image").onchange=e=>{const file=e.target.files[0];if(file)$("#product-preview").src=URL.createObjectURL(file)};bindComplementEditor();$("#save-product").onclick=()=>saveProduct(product)}
async function saveProduct(product){const form=$("#product-form");if(!form.reportValidity())return;const fd=new FormData(form);const price=Math.round(Number(String(fd.get("price")).replace(",","."))*100);if(!Number.isFinite(price)||price<=0)return toast("Informe um valor válido");const complements=[...document.querySelectorAll(".admin-complement-row")].map(row=>({name:row.querySelector("[data-complement-name]").value.trim(),price_cents:Math.max(0,Math.round(Number(row.querySelector("[data-complement-price]").value.replace(",","."))*100)||0),max_quantity:Math.max(1,Math.min(20,Number(row.querySelector("[data-complement-max]").value)||1))})).filter(option=>option.name);fd.set("price_cents",String(price));fd.set("complements_json",JSON.stringify(complements));for(const name of ["is_available","is_promo"])fd.set(name,form.elements[name].checked?"1":"0");const btn=$("#save-product");btn.disabled=true;try{await api(product?`/api/admin/products/${product.id}`:"/api/admin/products",{method:product?"PATCH":"POST",body:fd});state.catalog=await api("/api/admin/products");closeLayer();renderAdmin();toast(product?"Produto atualizado":"Produto cadastrado")}catch(e){toast(e.message);btn.disabled=false}}
function revenueView(){const r=state.admin.revenue;if(!r)return `<div class="panel empty">Carregando faturamento...</div>`;const max=Math.max(1,...Object.values(r.by_payment));const payments=[["dinheiro","Dinheiro"],["pix","Pix"],["credito","Cartão de crédito"],["debito","Cartão de débito"]];return `<div class="revenue-filter panel"><div class="field"><label>Data inicial</label><input type="date" id="revenue-from" value="${esc(r.from)}"></div><div class="field"><label>Data final</label><input type="date" id="revenue-to" value="${esc(r.to)}"></div><button class="primary-btn" id="apply-revenue">Aplicar período</button></div><div class="stat-grid revenue-stats"><div class="stat accent"><div class="stat-label">Faturamento</div><div class="stat-value">${money(r.total_cents)}</div></div><div class="stat"><div class="stat-label">Pedidos</div><div class="stat-value">${r.order_count}</div></div><div class="stat"><div class="stat-label">Ticket médio</div><div class="stat-value">${money(r.average_cents)}</div></div><div class="stat"><div class="stat-label">Taxas de garçom</div><div class="stat-value">${money(r.waiter_fee_cents)}</div></div></div><div class="revenue-grid"><section class="panel"><div class="panel-head"><h2>Por forma de pagamento</h2></div><div class="payment-bars">${payments.map(([key,label])=>`<div class="payment-row"><div><strong>${label}</strong><span>${money(r.by_payment[key])}</span></div><div class="payment-track"><i style="width:${Math.round(r.by_payment[key]/max*100)}%"></i></div></div>`).join("")}</div></section><section class="panel"><div class="panel-head"><h2>Por origem</h2></div><div class="channel-summary"><div><span class="source-tag online">DELIVERY • SITE</span><strong>${money(r.by_channel.online)}</strong></div><div><span class="source-tag counter">LOCAL • BALCÃO</span><strong>${money(r.by_channel.counter)}</strong></div></div></section></div>`}
function deliveryFeeRule(row={neighborhood:"",fee_cents:0}){return `<div class="delivery-fee-rule"><div class="field"><label>Bairro</label><input data-delivery-neighborhood maxlength="100" value="${esc(row.neighborhood)}" placeholder="Ex.: São Gonçalo"></div><div class="field"><label>Taxa (R$)</label><input data-delivery-fee inputmode="decimal" value="${(Number(row.fee_cents||0)/100).toFixed(2).replace(".",",")}" placeholder="0,00"></div><button type="button" class="icon-btn remove-delivery-rule" aria-label="Remover bairro">×</button></div>`}
function settingsView(){const s=state.catalog.settings,p=state.admin.printStatus||{},rules=s.delivery_neighborhood_fees||[];return `<form id="settings-form" class="settings-stack"><section class="panel"><div class="panel-head"><div><h2>Funcionamento e contato</h2><span class="muted">As mudanças aparecem imediatamente no cardápio.</span></div><button type="button" class="switch ${s.is_open?"on":""}" id="store-open" aria-label="Loja aberta"></button></div><div class="settings-grid"><div class="field"><label>Horário de encerramento</label><input name="closing_time" value="${esc(s.closing_time)}"></div><div class="field"><label>Pedido mínimo (R$)</label><input name="minimum_order" inputmode="decimal" value="${(s.minimum_order_cents/100).toFixed(2).replace(".",",")}"></div><div class="field"><label>Tempo de entrega</label><input name="delivery_eta" value="${esc(s.delivery_eta)}"></div><div class="field"><label>Tempo de retirada</label><input name="pickup_eta" value="${esc(s.pickup_eta)}"></div><div class="field"><label>Telefone</label><input name="phone" value="${esc(s.phone)}"></div><div class="field"><label>Endereço</label><input name="address" value="${esc(s.address)}"></div></div></section><section class="panel"><div class="panel-head"><div><h2>Taxas de entrega por bairro</h2><span class="muted">Sem bairro cadastrado, a entrega fica sem taxa.</span></div><button type="button" class="secondary-btn" id="add-delivery-rule">＋ Adicionar bairro</button></div><div id="delivery-fee-rules" class="delivery-fee-rules">${rules.map(deliveryFeeRule).join("")||'<div class="empty small-empty">Nenhum bairro com taxa. A entrega está gratuita.</div>'}</div><div class="surcharge-box"><label class="check-row"><input type="checkbox" name="delivery_surcharge_enabled" ${s.delivery_surcharge_enabled?"checked":""}><span><strong>Aplicar acréscimo temporário</strong><small>Útil em dias chuvosos ou condições especiais.</small></span></label><div class="settings-grid"><div class="field"><label>Descrição do acréscimo</label><input name="delivery_surcharge_label" maxlength="80" value="${esc(s.delivery_surcharge_label||"Acréscimo em dias chuvosos")}"></div><div class="field"><label>Acréscimo (%)</label><input type="number" name="delivery_surcharge_percent" min="0" max="100" value="${s.delivery_surcharge_percent||0}"></div></div></div></section><section class="panel"><div class="panel-head"><div><h2>Taxa de garçom</h2><span class="muted">Aplicada somente quando for marcada no pedido do balcão.</span></div><label class="check-row inline"><input type="checkbox" name="waiter_fee_enabled" ${s.waiter_fee_enabled?"checked":""}><span>Ativa</span></label></div><div class="settings-grid one-line"><div class="field"><label>Percentual da taxa (%)</label><input type="number" name="waiter_fee_percent" min="0" max="30" value="${s.waiter_fee_percent||10}"></div></div></section><section class="panel print-panel"><div class="panel-head"><div><h2>Impressão automática</h2><span class="muted">Conecta o site às impressoras instaladas no Windows.</span></div><span class="connection-pill ${p.configured?"ready":""}">${p.configured?"Configurado":"Aguardando configuração"}</span></div><div class="settings-grid"><div class="field"><label>Nome da impressora do caixa</label><input name="reception_printer" value="${esc(s.reception_printer||"")}" placeholder="Ex.: EPSON TM-T20X Receipt"></div><div class="field"><label>Nome da impressora da cozinha</label><input name="kitchen_printer" value="${esc(s.kitchen_printer||"")}" placeholder="Ex.: ELGIN i9 Cozinha"></div><div class="field key-field"><label>Chave de conexão</label><div class="field-action"><input name="print_bridge_key" placeholder="${s.print_bridge_configured?"Chave já configurada — deixe vazio para manter":"Gere uma chave segura"}"><button type="button" class="secondary-btn" id="generate-print-key">Gerar</button></div></div><label class="check-row print-enable"><input type="checkbox" name="auto_print_enabled" ${s.auto_print_enabled?"checked":""}><span><strong>Imprimir todos os pedidos automaticamente</strong><small>Inclui pedidos do site e do balcão, com uma via para o caixa e outra para a cozinha.</small></span></label></div><div class="print-guide"><strong>Como ativar no computador da acaiteria</strong><ol><li>Instale as duas impressoras no Windows e faça uma página de teste.</li><li>Copie os nomes exatos delas para os campos acima.</li><li>Gere uma chave, salve e baixe o conector gratuito.</li><li>Abra o arquivo no computador do caixa e mantenha a janela funcionando.</li></ol><div class="print-actions"><button type="button" class="secondary-btn" id="download-bridge">Baixar conector para Windows</button><span>${p.pending||0} impressões na fila • ${p.printed||0} concluídas</span></div></div></section><div class="settings-save"><button class="primary-btn">Salvar configurações</button></div></form>`}
function bindAdmin(){document.querySelectorAll("[data-admin-view]").forEach(b=>b.onclick=async()=>{state.admin.view=b.dataset.adminView;if(["pos","products","settings"].includes(state.admin.view))state.catalog=await api("/api/admin/products");if(["pos","tables"].includes(state.admin.view))state.admin.tables=await api("/api/admin/tables");if(state.admin.view==="revenue")await loadRevenue();if(state.admin.view==="settings")state.admin.printStatus=await api("/api/admin/print-status");renderAdmin()});document.querySelectorAll("[data-admin-action]").forEach(b=>b.onclick=async()=>{if(b.dataset.adminAction==="logout"){await api("/api/admin/logout",{method:"POST"});location.reload()}else location.href="/"});document.querySelectorAll("[data-status-id]").forEach(s=>s.onchange=async()=>{await api(`/api/admin/orders/${encodeURIComponent(s.dataset.statusId)}`,{method:"PATCH",body:JSON.stringify({status:s.value})});toast("Status atualizado");await loadAdminOrders();if(state.admin.view==="tables")state.admin.tables=await api("/api/admin/tables");renderAdmin()});document.querySelectorAll("[data-payment-order]").forEach(b=>b.onclick=async()=>{const o=state.admin.orders.find(x=>x.id===b.dataset.paymentOrder);await api(`/api/admin/orders/${encodeURIComponent(o.id)}/payment`,{method:"PATCH",body:JSON.stringify({payment_status:o.payment_status==="aberto"?"pago":"aberto"})});toast("Pagamento atualizado");await loadAdminOrders();renderAdmin()});document.querySelectorAll("[data-edit-order]").forEach(b=>b.onclick=()=>openOrderEditor(b.dataset.editOrder));document.querySelectorAll("[data-cancel-order]").forEach(b=>b.onclick=()=>openCancelOrder(b.dataset.cancelOrder));document.querySelectorAll("[data-order-details]").forEach(card=>{card.onclick=e=>{if(e.target.closest("button,select,a,input,textarea,label"))return;openOrderDetails(card.dataset.orderDetails)};card.onkeydown=e=>{if(e.target===card&&(e.key==="Enter"||e.key===" ")){e.preventDefault();openOrderDetails(card.dataset.orderDetails)}}});document.querySelectorAll("[data-order-filter]").forEach(b=>b.onclick=()=>{state.admin.orderFilter=b.dataset.orderFilter;renderAdmin()});if(state.admin.view==="pos")bindPos();if(state.admin.view==="products")bindProducts();if(state.admin.view==="revenue")bindRevenue();if(state.admin.view==="settings")bindSettings()}
function bindPos(){document.querySelectorAll("[data-pos-add]").forEach(b=>b.onclick=()=>openProduct(Number(b.dataset.posAdd),state.admin.posCart,()=>renderAdmin()));document.querySelectorAll("[data-cart-q]").forEach(b=>b.onclick=()=>{updateQty(b.dataset.key,Number(b.dataset.cartQ),state.admin.posCart);renderAdmin()});if($("#pos-waiter-fee"))$("#pos-waiter-fee").onchange=e=>{state.admin.posWaiterFee=e.target.checked;renderAdmin()};$("#pos-search").oninput=e=>{const q=e.target.value.toLowerCase();document.querySelectorAll("[data-pos-add]").forEach(b=>{const p=state.catalog.products.find(x=>x.id===Number(b.dataset.posAdd));b.classList.toggle("hidden",!p.name.toLowerCase().includes(q))})};const type=$("[name=order_type]"),tableField=$("#pos-table-field"),table=$("[name=table_number]"),finish=$("#pos-finish"),syncTableRequirement=()=>{const local=type.value==="pickup";tableField.classList.toggle("hidden",!local);table.required=local;finish.disabled=local&&!table.value};type.onchange=syncTableRequirement;table.onchange=syncTableRequirement;syncTableRequirement();finish.onclick=finishPos}
async function finishPos(){const fd=new FormData($("#pos-form"));const btn=$("#pos-finish");if(fd.get("order_type")==="pickup"&&!fd.get("table_number"))return toast("Selecione uma mesa disponível.");btn.disabled=true;try{const order=await api("/api/admin/orders",{method:"POST",body:JSON.stringify({customer_name:fd.get("customer_name"),table_number:fd.get("table_number"),order_type:fd.get("order_type"),payment_method:fd.get("payment_method"),payment_status:fd.get("payment_status"),notes:fd.get("notes"),apply_waiter_fee:state.admin.posWaiterFee,items:state.admin.posCart.map(i=>({product_id:i.product.id,quantity:i.quantity}))})});state.admin.posCart=[];state.admin.posWaiterFee=false;toast(`Pedido ${order.id} registrado${order.table_number?` na mesa ${order.table_number}`:""}`);state.admin.view="orders";await loadAdminOrders();renderAdmin()}catch(e){toast(e.message);btn.disabled=false}}
function bindProducts(){$("#new-product").onclick=()=>openProductEditor();document.querySelectorAll("[data-edit-product]").forEach(b=>b.onclick=()=>openProductEditor(Number(b.dataset.editProduct)));document.querySelectorAll("[data-category-move]").forEach(button=>button.onclick=async()=>{const categories=[...(state.catalog.categories||[])],index=Number(button.dataset.categoryIndex),next=button.dataset.categoryMove==="up"?index-1:index+1;if(next<0||next>=categories.length)return;[categories[index],categories[next]]=[categories[next],categories[index]];const result=await api("/api/admin/categories/order",{method:"PATCH",body:JSON.stringify({categories})});state.catalog.categories=result.categories;state.catalog.products.sort((a,b)=>result.categories.indexOf(a.category)-result.categories.indexOf(b.category)||a.sort_order-b.sort_order);renderAdmin();toast("Ordem das categorias atualizada")});document.querySelectorAll("[data-toggle-id]").forEach(b=>b.onclick=async()=>{const p=state.catalog.products.find(x=>x.id===Number(b.dataset.toggleId));await api(`/api/admin/products/${p.id}`,{method:"PATCH",body:JSON.stringify({is_available:!p.is_available})});p.is_available=!p.is_available;renderAdmin();toast("Disponibilidade atualizada")});document.querySelectorAll("[data-price-id]").forEach(inp=>inp.onchange=async()=>{const id=Number(inp.dataset.priceId),value=Math.round(Number(inp.value.replace(",","."))*100);if(!Number.isFinite(value)||value<=0)return toast("Preço inválido");await api(`/api/admin/products/${id}`,{method:"PATCH",body:JSON.stringify({price_cents:value})});state.catalog.products.find(p=>p.id===id).price_cents=value;toast("Preço atualizado")})}
async function loadRevenue(from,to){const q=new URLSearchParams();if(from)q.set("from",from);if(to)q.set("to",to);state.admin.revenue=await api(`/api/admin/revenue?${q}`)}
function bindRevenue(){$("#apply-revenue").onclick=async()=>{const btn=$("#apply-revenue");btn.disabled=true;await loadRevenue($("#revenue-from").value,$("#revenue-to").value);renderAdmin()}}
function bindSettings(){$("#store-open").onclick=()=>{$("#store-open").classList.toggle("on")};$("#generate-print-key").onclick=()=>{const bytes=crypto.getRandomValues(new Uint8Array(18));$("[name=print_bridge_key]").value=Array.from(bytes,b=>b.toString(16).padStart(2,"0")).join("")};$("#download-bridge").onclick=downloadPrintBridge;const rules=$("#delivery-fee-rules");$("#add-delivery-rule").onclick=()=>{if(rules.querySelector(".small-empty"))rules.innerHTML="";rules.insertAdjacentHTML("beforeend",deliveryFeeRule());bindDeliveryRuleButtons()};function bindDeliveryRuleButtons(){document.querySelectorAll(".remove-delivery-rule").forEach(btn=>btn.onclick=()=>{btn.closest(".delivery-fee-rule").remove();if(!rules.querySelector(".delivery-fee-rule"))rules.innerHTML='<div class="empty small-empty">Nenhum bairro com taxa. A entrega está gratuita.</div>'})}bindDeliveryRuleButtons();$("#settings-form").onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);const delivery_neighborhood_fees=[...document.querySelectorAll(".delivery-fee-rule")].map(row=>({neighborhood:row.querySelector("[data-delivery-neighborhood]").value.trim(),fee_cents:Math.max(0,Math.round(Number(row.querySelector("[data-delivery-fee]").value.replace(",","."))*100)||0)})).filter(rule=>rule.neighborhood);const payload={is_open:$("#store-open").classList.contains("on"),closing_time:fd.get("closing_time"),minimum_order_cents:Math.max(0,Math.round(Number(String(fd.get("minimum_order")).replace(",","."))*100)||0),delivery_eta:fd.get("delivery_eta"),pickup_eta:fd.get("pickup_eta"),phone:fd.get("phone"),address:fd.get("address"),delivery_neighborhood_fees,delivery_surcharge_enabled:e.currentTarget.elements.delivery_surcharge_enabled.checked,delivery_surcharge_percent:Number(fd.get("delivery_surcharge_percent")),delivery_surcharge_label:fd.get("delivery_surcharge_label"),waiter_fee_enabled:e.currentTarget.elements.waiter_fee_enabled.checked,waiter_fee_percent:Number(fd.get("waiter_fee_percent")),auto_print_enabled:e.currentTarget.elements.auto_print_enabled.checked,reception_printer:fd.get("reception_printer"),kitchen_printer:fd.get("kitchen_printer"),print_bridge_key:fd.get("print_bridge_key")};await api("/api/admin/settings",{method:"PATCH",body:JSON.stringify(payload)});state.catalog=await api("/api/admin/products");state.admin.printStatus=await api("/api/admin/print-status");toast("Configurações salvas");renderAdmin()}}
function setupTableSettings(){const form=$("#settings-form"),s=state.catalog.settings;if(!form||form.querySelector("[name=table_count]"))return;form.insertAdjacentHTML("afterbegin",`<section class="panel table-settings"><div class="panel-head"><div><h2>Mesas do salão</h2><span class="muted">Defina a quantidade de mesas para liberar o controle no balcão e no painel do telão.</span></div><a class="secondary-btn" href="/mesas" target="_blank" rel="noopener noreferrer">Abrir telão</a></div><div class="settings-grid one-line"><div class="field"><label>Quantidade de mesas</label><input type="number" name="table_count" min="0" max="200" value="${Number(s.table_count||0)}"><small>As mesas ocupadas são bloqueadas automaticamente para novos pedidos.</small></div></div></section>`);form.addEventListener("submit",async e=>{e.preventDefault();e.stopImmediatePropagation();const fd=new FormData(form),delivery_neighborhood_fees=[...document.querySelectorAll(".delivery-fee-rule")].map(row=>({neighborhood:row.querySelector("[data-delivery-neighborhood]").value.trim(),fee_cents:Math.max(0,Math.round(Number(row.querySelector("[data-delivery-fee]").value.replace(",","."))*100)||0)})).filter(rule=>rule.neighborhood),payload={is_open:$("#store-open").classList.contains("on"),closing_time:fd.get("closing_time"),minimum_order_cents:Math.max(0,Math.round(Number(String(fd.get("minimum_order")).replace(",","."))*100)||0),delivery_eta:fd.get("delivery_eta"),pickup_eta:fd.get("pickup_eta"),phone:fd.get("phone"),address:fd.get("address"),table_count:Math.max(0,Math.min(200,Number(fd.get("table_count"))||0)),delivery_neighborhood_fees,delivery_surcharge_enabled:form.elements.delivery_surcharge_enabled.checked,delivery_surcharge_percent:Number(fd.get("delivery_surcharge_percent")),delivery_surcharge_label:fd.get("delivery_surcharge_label"),waiter_fee_enabled:form.elements.waiter_fee_enabled.checked,waiter_fee_percent:Number(fd.get("waiter_fee_percent")),auto_print_enabled:form.elements.auto_print_enabled.checked,reception_printer:fd.get("reception_printer"),kitchen_printer:fd.get("kitchen_printer"),print_bridge_key:fd.get("print_bridge_key")};try{await api("/api/admin/settings",{method:"PATCH",body:JSON.stringify(payload)});state.catalog=await api("/api/admin/products");state.admin.printStatus=await api("/api/admin/print-status");toast("Configurações salvas");renderAdmin()}catch(error){toast(error.message)}} ,true)}
async function downloadPrintBridge(){try{const res=await fetch("/api/admin/print-bridge.ps1");if(!res.ok){const data=await res.json().catch(()=>({}));throw new Error(data.error||"Salve as configurações primeiro.")}const url=URL.createObjectURL(await res.blob());const a=document.createElement("a");a.href=url;a.download="mb-acaiteria-impressao.ps1";a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast("Conector baixado")}catch(e){toast(e.message)}}

function availabilityView(){const s=state.catalog.settings,hours=s.business_hours||[];return `<form id="availability-form" class="settings-stack"><section class="panel availability-status ${s.is_open?"open":"closed"}"><div class="availability-icon">${s.is_open?"✓":"×"}</div><div><span class="eyebrow">STATUS NO SITE</span><h2>${s.is_open?"Loja aberta e recebendo pedidos":"Loja fechada para pedidos"}</h2><p>${s.manual_closed?"Fechamento manual ativado.":s.scheduled_open?"Dentro do horário programado.":"Fora do horário programado."}</p></div></section><section class="panel"><div class="panel-head"><div><h2>Fechamento manual</h2><span class="muted">Use em imprevistos, feriados ou quando precisar encerrar mais cedo.</span></div><label class="check-row inline"><input type="checkbox" name="manual_closed" ${s.manual_closed?"checked":""}><span><strong>Fechar agora</strong></span></label></div><div class="settings-grid one-line"><div class="field"><label>Mensagem para os clientes</label><input name="manual_closed_reason" maxlength="160" value="${esc(s.manual_closed_reason||"")}" placeholder="Ex.: Hoje encerramos mais cedo. Voltamos amanhã!"></div></div></section><section class="panel"><div class="panel-head"><div><h2>Horários semanais</h2><span class="muted">Padrão: quarta a segunda, 17:30 às 23:20; terça-feira é folga.</span></div></div><div class="business-hours-list">${hours.map(day=>`<div class="business-hours-row" data-business-day="${day.day}"><label class="check-row"><input type="checkbox" data-hours-enabled ${day.enabled?"checked":""}><span><strong>${esc(day.label)}</strong></span></label><div class="field"><label>Abre</label><input type="time" data-hours-open value="${esc(day.open)}"></div><div class="field"><label>Fecha</label><input type="time" data-hours-close value="${esc(day.close)}"></div></div>`).join("")}</div></section><div class="settings-save"><button class="primary-btn">Salvar funcionamento</button></div></form>`}
function bindAvailability(){$("#availability-form").onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector("button.primary-btn"),business_hours=[...document.querySelectorAll("[data-business-day]")].map(row=>({day:Number(row.dataset.businessDay),label:row.querySelector("strong").textContent,enabled:row.querySelector("[data-hours-enabled]").checked,open:row.querySelector("[data-hours-open]").value,close:row.querySelector("[data-hours-close]").value}));button.disabled=true;try{await api("/api/admin/store-availability",{method:"PATCH",body:JSON.stringify({manual_closed:form.elements.manual_closed.checked,manual_closed_reason:form.elements.manual_closed_reason.value,business_hours})});state.catalog=await api("/api/admin/products");renderAdmin();toast("Funcionamento atualizado no site")}catch(error){toast(error.message);button.disabled=false}}}
