state.cashier.selfServiceItems=state.cashier.selfServiceItems||[];
state.cashier.activeOrder=null;

function cashierSelfServiceItems(){
  const cashier=state.cashier;
  if(!Array.isArray(cashier.selfServiceItems))cashier.selfServiceItems=[];
  if(cashier.selfService){cashier.selfServiceItems.push(cashier.selfService);cashier.selfService=null}
  return cashier.selfServiceItems;
}

function cashierAddedTotal(){
  const cashier=state.cashier;
  return cartTotal(cashier.posCart)+cashierSelfServiceItems().reduce((sum,item)=>sum+Math.round(Number(item.grams||0)*Number(item.price_per_kg_cents||0)/1000),0);
}

cashierPosTotal=cashierAddedTotal;
const cashierOrderCardBase=cashierOrderCard;
cashierOrderCard=function(order){
  const canContinue=order.channel==="counter"&&order.payment_status==="aberto"&&order.status!=="cancelado";
  return cashierOrderCardBase(order).replace('<div class="order-actions">',`<div class="order-actions">${canContinue?`<button class="secondary-btn compact" data-cashier-continue="${esc(order.id)}">Adicionar itens</button>`:""}`);
};

function openCashierSelfServiceV2(){
  const cashier=state.cashier;
  let scale=cashier.scale||{},price=Math.max(1,Number(scale.price_per_kg_cents||3000));
  const isFresh=reading=>{const age=reading?.captured_at?Date.now()-Date.parse(reading.captured_at):Infinity;return Boolean(reading?.grams&&Number.isFinite(age)&&age>=0&&age<=120000)};
  let fresh=isFresh(scale);
  let manual=false;
  layer(`<div class="drawer-header"><div><h2>⚖ Venda por peso · Self-service</h2><span class="muted">${cashier.activeOrder?`Adicionar ao pedido ${esc(cashier.activeOrder.id)}`:`Unidade ${esc(cashier.name)}`}</span></div><button class="icon-btn" data-close aria-label="Fechar">×</button></div><div class="drawer-content self-service-dialog"><div class="self-service-notice"><strong id="cashier-ss-price">Preço: ${money(price)}/kg</strong><p>Com o agente da balança rodando no computador do caixa, basta pesar: o peso aparece aqui automaticamente. O peso manual fica registrado na auditoria.</p></div><div class="self-service-actions"><button class="secondary-btn" id="cashier-ss-manual">Peso manual</button></div><p class="muted" id="cashier-ss-status">${fresh?`Leitura disponível: ${(scale.grams/1000).toFixed(3).replace(".",",")} kg`:"Aguardando uma leitura da balança..."}</p><div id="cashier-ss-manual-fields" class="compact-field hidden"><div class="field"><label>Peso bruto (kg)</label><input id="cashier-ss-gross" inputmode="decimal" placeholder="0,000"></div><div class="field"><label>Tara do recipiente (kg)</label><input id="cashier-ss-tare" inputmode="decimal" value="0,000"></div></div><section class="self-service-total"><div><span>Peso líquido</span><strong id="cashier-ss-weight">${fresh?`${(scale.grams/1000).toFixed(3).replace(".",",")} kg`:"0,000 kg"}</strong></div><div><span>Valor calculado</span><strong id="cashier-ss-total">${fresh?money(Math.round(scale.grams*price/1000)):money(0)}</strong></div></section></div><div class="drawer-footer"><button class="secondary-btn" data-close>Cancelar</button><button class="primary-btn" id="cashier-ss-confirm" ${fresh?"":"disabled"}>Adicionar ao pedido</button></div>`,"drawer self-service-drawer");
  const parse=value=>Math.max(0,Math.round(Number(String(value||"").trim().replace(",","."))*1000)||0);
  const manualWeight=()=>Math.max(0,parse(document.getElementById("cashier-ss-gross")?.value)-parse(document.getElementById("cashier-ss-tare")?.value));
  const weight=()=>manual?manualWeight():(fresh?Number(scale.grams||0):0);
  const sync=()=>{const grams=weight();$("#cashier-ss-weight").textContent=`${(grams/1000).toFixed(3).replace(".",",")} kg`;$("#cashier-ss-total").textContent=money(Math.round(grams*price/1000));$("#cashier-ss-price").textContent=`Preço: ${money(price)}/kg`;$("#cashier-ss-confirm").disabled=!grams||(!manual&&!fresh)};
  let polling=false;
  const loadScale=async()=>{if(polling||manual)return;polling=true;try{const reading=await api("/api/cashier/scale/current");scale=reading||{};cashier.scale=scale;price=Math.max(1,Number(scale.price_per_kg_cents||price));fresh=isFresh(scale);$("#cashier-ss-status").textContent=fresh?`Leitura disponível: ${(Number(scale.grams)/1000).toFixed(3).replace(".",",")} kg`:"Aguardando uma leitura da balança...";sync()}catch{}finally{polling=false}};
  const pollId=setInterval(loadScale,750),closeSelfService=()=>{clearInterval(pollId);closeLayer()};
  document.querySelectorAll("[data-close]").forEach(button=>button.onclick=closeSelfService);
  loadScale();
  $("#cashier-ss-manual").onclick=()=>{
    manual=!manual;
    $("#cashier-ss-manual-fields").classList.toggle("hidden",!manual);
    $("#cashier-ss-manual").textContent=manual?"Usar leitura da balança":"Peso manual";
    $("#cashier-ss-status").textContent=manual?"Peso manual será registrado na auditoria do sistema.":(fresh?`Leitura disponível: ${(scale.grams/1000).toFixed(3).replace(".",",")} kg`:"Aguardando uma leitura válida da balança.");
    sync();
  };
  const syncManual=()=>{if(manual)sync()};
  [$("#cashier-ss-gross"),$("#cashier-ss-tare")].forEach(input=>["input","change","keyup","blur"].forEach(eventName=>input.addEventListener(eventName,syncManual)));
  $("#cashier-ss-confirm").onclick=()=>{
    const grams=weight(); if(!grams)return;
    cashierSelfServiceItems().push({key:`self-service-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,grams,captured_at:manual?"":scale.captured_at,price_per_kg_cents:price,manual});
    clearInterval(pollId); closeLayer(); renderCashierPanel(); toast("Self-service adicionado ao pedido");
  };
}

