renderCashierPanel=function(){
  const cashier=state.cashier; state.catalog=cashier.catalog;
  if(cashier.view==="revenue")cashier.view="orders";
  let title="Pedidos",content=cashierOrdersView();
  if(cashier.view==="pos"){title=cashier.activeOrder?`Pedido ${cashier.activeOrder.id}`:"Novo pedido no balcão";content=cashierPosViewV2()}
  if(cashier.view==="products"){title="Produtos";content=cashierProductsView()}
  $("#app").innerHTML=cashierLayout(content,title);
  if(cashier.view==="pos"&&!cashier.activeOrder){const paymentStatus=$("#cashier-pos-form [name=payment_status]");if(paymentStatus)paymentStatus.value="aberto"}
  applyBlissBrand(); bindCashierV2();
};

async function startCashierContinuation(order){
  const cashier=state.cashier;
  cashier.activeOrder=order; cashier.posCart=[]; cashier.selfServiceItems=[]; cashier.selfService=null; cashier.view="pos";
  await refreshCashier(true);
  cashier.activeOrder=cashier.orders.find(item=>item.id===order.id)||order;
  renderCashierPanel();
}

async function finishCashierPosV2(){
  const cashier=state.cashier,button=$("#cashier-pos-finish"),selfItems=cashierSelfServiceItems();
  if(!cashier.posCart.length&&!selfItems.length)return;
  button.disabled=true;
  try{
    const items=cashier.posCart.map(item=>({product_id:item.product.id,quantity:item.quantity,complements:item.complements||[],notes:item.notes||""}));
    const self_service_items=selfItems.map(item=>({grams:item.grams,captured_at:item.captured_at,manual:Boolean(item.manual)}));
    if(cashier.activeOrder){
      const result=await api(`/api/cashier/orders/${encodeURIComponent(cashier.activeOrder.id)}/items`,{method:"POST",body:JSON.stringify({items,self_service_items})});
      cashier.activeOrder=null; cashier.posCart=[]; cashier.selfServiceItems=[]; cashier.view="orders";
      await refreshCashier(); renderCashierPanel(); toast(`${result.items_added} item(ns) adicionado(s) ao pedido ${result.id}`); return;
    }
    const data=new FormData($("#cashier-pos-form"));
    const order=await api("/api/cashier/orders",{method:"POST",body:JSON.stringify({customer_name:data.get("customer_name"),order_type:"pickup",payment_method:data.get("payment_method"),payment_status:data.get("payment_status"),notes:data.get("notes"),self_service_items,items})});
    cashier.posCart=[]; cashier.selfServiceItems=[]; cashier.view="orders";
    await refreshCashier(); renderCashierPanel(); toast(`Pedido ${order.id} registrado no caixa ${cashier.name}`);
  }catch(error){toast(error.message);button.disabled=false}
}

function bindCashierV2(){
  const cashier=state.cashier;
  document.querySelectorAll("[data-cashier-view]").forEach(button=>button.onclick=async()=>{cashier.view=button.dataset.cashierView;if(["revenue","pos","products"].includes(cashier.view))await refreshCashier(cashier.view==="pos"||cashier.view==="products");renderCashierPanel()});
  document.querySelectorAll("[data-cashier-action]").forEach(button=>button.onclick=async()=>{clearInterval(cashier.refresh);await api("/api/cashier/logout",{method:"POST"});cashier.catalog=null;cashier.selfService=null;cashier.selfServiceItems=[];cashier.activeOrder=null;startCashier()});
  document.querySelectorAll("[data-cashier-filter]").forEach(button=>button.onclick=()=>{cashier.orderFilter=button.dataset.cashierFilter;renderCashierPanel()});
  document.querySelectorAll("[data-cashier-status]").forEach(select=>select.onchange=async()=>{await api(`/api/cashier/orders/${encodeURIComponent(select.dataset.cashierStatus)}`,{method:"PATCH",body:JSON.stringify({status:select.value})});await refreshCashier();renderCashierPanel();toast("Status atualizado")});
  document.querySelectorAll("[data-cashier-payment]").forEach(button=>button.onclick=async()=>{const order=cashier.orders.find(item=>item.id===button.dataset.cashierPayment);await api(`/api/cashier/orders/${encodeURIComponent(order.id)}/payment`,{method:"PATCH",body:JSON.stringify({payment_status:order.payment_status==="aberto"?"pago":"aberto"})});await refreshCashier();renderCashierPanel();toast("Pagamento atualizado")});
  document.querySelectorAll("[data-cashier-continue]").forEach(button=>button.onclick=()=>{const order=cashier.orders.find(item=>item.id===button.dataset.cashierContinue);if(order)startCashierContinuation(order)});
  document.querySelectorAll("[data-cashier-product-toggle]").forEach(button=>button.onclick=async()=>{const product=cashier.catalog.products.find(item=>item.id===Number(button.dataset.cashierProductToggle));await api(`/api/cashier/products/${product.id}`,{method:"PATCH",body:JSON.stringify({is_available:!product.branch_available})});await refreshCashier(true);renderCashierPanel();toast("Disponibilidade atualizada")});
  if(cashier.view!=="pos")return;
  document.querySelectorAll("[data-cashier-add]").forEach(button=>button.onclick=()=>openProduct(Number(button.dataset.cashierAdd),cashier.posCart,renderCashierPanel));
  document.querySelectorAll("[data-cart-q]").forEach(button=>button.onclick=()=>{updateQty(button.dataset.key,Number(button.dataset.cartQ),cashier.posCart);renderCashierPanel()});
  $("#cashier-pos-search").oninput=event=>{const query=event.target.value.toLowerCase();document.querySelectorAll("[data-cashier-add]").forEach(button=>{const product=cashier.catalog.products.find(item=>item.id===Number(button.dataset.cashierAdd));button.classList.toggle("hidden",!product.name.toLowerCase().includes(query))})};
  $("#cashier-self-service").onclick=openCashierSelfServiceV2;
  document.querySelectorAll("[data-cashier-remove-scale]").forEach(button=>button.onclick=()=>{cashier.selfServiceItems=cashierSelfServiceItems().filter(item=>item.key!==button.dataset.cashierRemoveScale);renderCashierPanel()});
  const cancel=$("#cashier-pos-cancel");
  if(cancel)cancel.onclick=()=>{cashier.activeOrder=null;cashier.posCart=[];cashier.selfServiceItems=[];cashier.view="orders";renderCashierPanel()};
  $("#cashier-pos-finish").onclick=finishCashierPosV2;
}

// Painel do proprietário: visão consolidada e filtros independentes para cada unidade.
state.admin.branchFilter=state.admin.branchFilter||"all";
state.admin.revenueBranches=state.admin.revenueBranches||null;
const OWNER_BRANCHES=[{id:"acailandia",name:"São Gonçalo"}];
function ownerBranchName(id){return OWNER_BRANCHES.find(branch=>branch.id===id)?.name||"São Gonçalo"}
function ownerBranchStats(orders){const today=brazilDateKey(),todayOrders=orders.filter(order=>!order.created_at||brazilDateKey(order.created_at)===today);return {count:todayOrders.length,revenue:todayOrders.filter(order=>order.status!=="cancelado").reduce((sum,order)=>sum+Number(order.total_cents||0),0),open:todayOrders.filter(order=>order.payment_status==="aberto"&&order.status!=="cancelado").length}}
function ownerBranchSummaryCards(){return `<section class="owner-branch-summary">${OWNER_BRANCHES.map(branch=>{const stats=ownerBranchStats(state.admin.orders.filter(order=>order.branch_id===branch.id));return `<article class="owner-branch-card ${branch.id}"><span>${esc(branch.name)}</span><strong>${money(stats.revenue)}</strong><small>${stats.count} pedido(s) hoje • ${stats.open} em aberto</small></article>`}).join("")}</section>`}
const ownerOrderCardBase=orderCard;
orderCard=function(order){const tag=`<span class="owner-branch-tag acailandia">São Gonçalo</span>`;return ownerOrderCardBase(order).replace('<div class="order-card-head">',`${tag}<div class="order-card-head">`)};
ordersView=function(){const orders=state.admin.orders||[],stats=ownerBranchStats(orders),groups=[{title:"Novos",s:["novo"]},{title:"Em produção",s:["confirmado","preparando"]},{title:"Prontos",s:["pronto"]},{title:"Saiu para entrega",s:["saiu_entrega"],delivery:true},{title:"Finalizados",s:["concluido","cancelado"]}],filtered=state.admin.orderFilter==="all"?orders:orders.filter(order=>order.channel===state.admin.orderFilter);return `<div class="owner-branch-heading"><div><span class="eyebrow">VISÃO DO PROPRIETÁRIO</span><h2>São Gonçalo</h2><p>Pedidos e valores da única unidade da Açailandia.</p></div></div>${ownerBranchSummaryCards()}<div class="stat-grid"><div class="stat"><div class="stat-label">Pedidos hoje</div><div class="stat-value">${stats.count}</div></div><div class="stat"><div class="stat-label">Vendas hoje</div><div class="stat-value">${money(stats.revenue)}</div></div><div class="stat"><div class="stat-label">Em aberto</div><div class="stat-value">${stats.open}</div></div><div class="stat"><div class="stat-label">Unidade</div><div class="stat-value owner-unit-value">São Gonçalo</div></div></div><div class="view-toolbar owner-filter-toolbar"><div class="filter-tabs"><button class="${state.admin.orderFilter==="all"?"active":""}" data-order-filter="all">Todos</button><button class="${state.admin.orderFilter==="online"?"active":""}" data-order-filter="online">Delivery / site</button><button class="${state.admin.orderFilter==="counter"?"active":""}" data-order-filter="counter">Local / balcão</button></div></div><div class="order-board">${groups.map(group=>{const list=filtered.filter(order=>group.s.includes(order.status)&&(!group.delivery||order.order_type==="delivery"));return `<section class="order-column ${group.delivery?"delivery-column":""}"><h2 class="column-title">${group.title}<span class="column-count">${list.length}</span></h2>${list.length?list.map(orderCard).join(""):'<div class="empty panel">Nenhum pedido nesta unidade.</div>'}</section>`}).join("")}</div>`};
const ownerRevenueViewBase=revenueView;
revenueView=function(){const base=ownerRevenueViewBase(),branches=state.admin.revenueBranches;if(!branches)return base;const cards=OWNER_BRANCHES.map(branch=>{const revenue=branches[branch.id]||{};return `<article class="owner-revenue-card ${branch.id}"><span>${esc(branch.name)}</span><strong>${money(revenue.total_cents)}</strong><small>${Number(revenue.order_count||0)} pedido(s) • ticket médio ${money(revenue.average_cents)}</small><div><span>Site ${money(revenue.by_channel?.online)}</span><span>Balcão ${money(revenue.by_channel?.counter)}</span></div></article>`}).join("");return base.replace('<div class="stat-grid revenue-stats">',`<section class="owner-revenue-compare"><div class="panel-head"><div><h2>Faturamento por estabelecimento</h2><span class="muted">Comparativo do período selecionado.</span></div></div><div class="owner-revenue-cards">${cards}</div></section><div class="stat-grid revenue-stats">`)};
loadRevenue=async function(from,to){const params=new URLSearchParams();if(from)params.set("from",from);if(to)params.set("to",to);params.set("branch","acailandia");const report=await api(`/api/admin/revenue?${params.toString()}`);state.admin.revenue=report;state.admin.revenueBranches={acailandia:report}};
const bindAdminOwnerBase=bindAdmin;
bindAdmin=function(){bindAdminOwnerBase();document.querySelectorAll("[data-owner-branch]").forEach(button=>button.onclick=()=>{state.admin.branchFilter=button.dataset.ownerBranch;renderAdmin()})};

async function boot(){try{if(location.pathname==="/painel")return startAdmin();if(location.pathname==="/mesas")return startPublicTables();if(location.pathname==="/caixa"||location.pathname.startsWith("/caixa/"))return startCashier();try{const saved=localStorage.getItem("loja_last_order");if(saved)state.lastOrder={id:saved}}catch{}state.catalog=await api("/api/catalog?branch="+currentBranch());renderCustomer()}catch(e){$("#app").innerHTML=`<div class="boot"><div class="boot-mark">!</div><h2>Não foi possível carregar</h2><p>${esc(e.message)}</p><button class="primary-btn" onclick="location.reload()">Tentar novamente</button></div>`}}
boot();

