// Controles dos caixas: cada sessão só altera pedidos da sua própria unidade.
const blissCashierOrderCardActions=cashierOrderCard;
cashierOrderCard=function(order){
  const disabled=order.status==="cancelado"?"disabled":"";
  return blissCashierOrderCardActions(order).replace('<div class="order-actions">',`<div class="order-actions"><button class="secondary-btn compact" data-cashier-edit-order="${esc(order.id)}" ${disabled}>Editar</button><button class="danger-btn compact" data-cashier-cancel-order="${esc(order.id)}" ${disabled}>Cancelar</button><button class="danger-btn compact" data-cashier-delete-order="${esc(order.id)}">Excluir</button>`);
};

